/* DAWAH X — ahmad, অধ্যায় 81 · খণ্ড 81 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][81]=[[16001,16001,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلُ بْنُ إِسْمَاعِيلَ أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏مُنِيبٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏قَالَ بَلَغَ ‏ ‏رَجُلًا ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ سَتَرَ أَخَاهُ الْمُسْلِمَ فِي الدُّنْيَا سَتَرَهُ اللَّهُ يَوْمَ الْقِيَامَةِ فَرَحَلَ إِلَيْهِ وَهُوَ ‏ ‏بِمِصْرَ ‏ ‏فَسَأَلَهُ عَنْ الْحَدِيثِ قَالَ نَعَمْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ مَنْ سَتَرَ أَخَاهُ الْمُسْلِمَ فِي الدُّنْيَا سَتَرَهُ اللَّهُ يَوْمَ الْقِيَامَةِ قَالَ وَأَنَا قَدْ سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[16002,16002,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي الْخَيْرِ ‏ ‏أَنَّ ‏ ‏جُنَادَةَ بْنَ أَبِي أُمَيَّةَ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ رِجَالًا مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ بَعْضُهُمْ إِنَّ الْهِجْرَةَ قَدْ انْقَطَعَتْ فَاخْتَلَفُوا فِي ذَلِكَ قَالَ فَانْطَلَقْتُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّ أُنَاسًا يَقُولُونَ إِنَّ الْهِجْرَةَ قَدْ انْقَطَعَتْ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏الْهِجْرَةَ لَا تَنْقَطِعُ مَا كَانَ الْجِهَادُ ‏","","",""],[16003,16003,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏وَسُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏إِنْسَانٍ ‏ ‏مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ ‏ ‏الْقَسَامَةَ ‏ ‏كَانَتْ فِي الْجَاهِلِيَّةِ ‏ ‏قَسَامَةَ ‏ ‏الدَّمِ فَأَقَرَّهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى مَا كَانَتْ عَلَيْهِ فِي الْجَاهِلِيَّةِ وَقَضَى بِهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ أُنَاسٍ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏مِنْ ‏ ‏بَنِي حَارِثَةَ ‏ ‏ادَّعُوهُ عَلَى ‏ ‏الْيَهُودِ ‏","","",""],[16004,16004,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْجُرَيْرِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُبَيْدَ بْنَ الْقَعْقَاعِ ‏ ‏يُحَدِّثُ ‏ ‏رَجُلًا مِنْ ‏ ‏بَنِي حَنْظَلَةَ ‏ ‏قَالَ ‏ ‏رَمَقَ ‏ ‏رَجُلٌ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏يُصَلِّي فَجَعَلَ ‏ ‏يَقُولُ فِي صَلَاتِهِ اللَّهُمَّ اغْفِرْ لِي ذَنْبِي وَوَسِّعْ لِي فِي دَارِي وَبَارِكْ لِي فِيمَا رَزَقْتَنِي ‏","","",""],[16005,16005,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي عِمْرَانَ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِجُنْدُبٍ ‏ ‏إِنِّي قَدْ ‏ ‏بَايَعْتُ ‏ ‏هَؤُلَاءِ ‏ ‏يَعْنِي ‏ ‏ابْنَ الزُّبَيْرِ ‏ ‏وَإِنَّهُمْ يُرِيدُونَ أَنْ أَخْرُجَ مَعَهُمْ إِلَى ‏ ‏الشَّامِ ‏ ‏فَقَالَ أَمْسِكْ فَقُلْتُ إِنَّهُمْ يَأْبَوْنَ فَقَالَ افْتَدِ بِمَالِكَ قَالَ قُلْتُ إِنَّهُمْ يَأْبَوْنَ إِلَّا أَنْ أَضْرِبَ مَعَهُمْ بِالسَّيْفِ ‏ ‏فَقَالَ ‏ ‏جُنْدُبٌ ‏ ‏حَدَّثَنِي ‏ ‏فُلَانٌ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَجِيءُ الْمَقْتُولُ بِقَاتِلِهِ يَوْمَ الْقِيَامَةِ فَيَقُولُ يَا رَبِّ سَلْ هَذَا فِيمَ قَتَلَنِي ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏فَأَحْسِبُهُ قَالَ فَيَقُولُ عَلَامَ قَتَلْتَهُ ‏ ‏فَيَقُولُ قَتَلْتُهُ عَلَى مُلْكِ فُلَانٍ قَالَ ‏ ‏فَقَالَ ‏ ‏جُنْدُبٌ ‏ ‏فَاتَّقِهَا ‏","","",""],[16006,16006,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُوحٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ هِشَامٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْكُبُ عَلَى رَأْسِهِ الْمَاءَ بِالسُّقْيَا ‏ ‏إِمَّا مِنْ الْحَرِّ وَإِمَّا مِنْ الْعَطَشِ ‏ ‏وَهُوَ صَائِمٌ ثُمَّ ‏ ‏لَمْ يَزَلْ صَائِمًا حَتَّى أَتَى ‏ ‏كَدِيدًا ‏ ‏ثُمَّ دَعَا بِمَاءٍ فَأَفْطَرَ وَأَفْطَرَ النَّاسُ وَهُوَ عَامُ الْفَتْحِ ‏","","",""],[16007,16007,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَامَ فِي سَفَرٍ عَامَ الْفَتْحِ وَأَمَرَ أَصْحَابَهُ بِالْإِفْطَارِ وَقَالَ إِنَّكُمْ تَلْقَوْنَ عَدُوًّا لَكُمْ فَتَقَوَّوْا فَقِيلَ يَا رَسُولَ اللَّهِ إِنَّ النَّاسَ قَدْ صَامُوا لِصِيَامِكَ فَلَمَّا أَتَى ‏ ‏الْكَدِيدَ ‏ ‏أَفْطَرَ قَالَ الَّذِي حَدَّثَنِي فَلَقَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصُبُّ الْمَاءَ عَلَى رَأْسِهِ مِنْ الْحَرِّ وَهُوَ صَائِمٌ ‏","","",""],[16008,16008,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏أَشْعَثَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شَيْخٌ ‏ ‏مِنْ ‏ ‏بَنِي مَالِكِ بْنِ كِنَانَةَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِسُوقِ ‏ ‏ذِي الْمَجَازِ ‏ ‏يَتَخَلَّلُهَا يَقُولُ يَا أَيُّهَا النَّاسُ قُولُوا لَا إِلَهَ إِلَّا اللَّهُ تُفْلِحُوا قَالَ ‏ ‏وَأَبُو جَهْلٍ ‏ ‏يَحْثِي ‏ ‏عَلَيْهِ التُّرَابَ وَيَقُولُ يَا أَيُّهَا النَّاسُ لَا يَغُرَّنَّكُمْ هَذَا عَنْ دِينِكُمْ فَإِنَّمَا يُرِيدُ لِتَتْرُكُوا آلِهَتَكُمْ وَتَتْرُكُوا اللَّاتَ وَالْعُزَّى قَالَ وَمَا يَلْتَفِتُ إِلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قُلْنَا ‏ ‏انْعَتْ ‏ ‏لَنَا رَسُولَ اللَّهِ قَالَ ‏ ‏بَيْنَ ‏ ‏بُرْدَيْنِ ‏ ‏أَحْمَرَيْنِ ‏ ‏مَرْبُوعٌ ‏ ‏كَثِيرُ اللَّحْمِ حَسَنُ الْوَجْهِ شَدِيدُ سَوَادِ الشَّعْرِ أَبْيَضُ شَدِيدُ الْبَيَاضِ ‏ ‏سَابِغُ ‏ ‏الشَّعْرِ ‏","","",""],[16009,16009,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏أَشْعَثَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ بْنِ هِلَالٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ قَوْمِهِ ‏ ‏قَالَ ‏ ‏كَانَ يَقُولُ فِي خِلَافَةِ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏لَا يَمُوتُ ‏ ‏عُثْمَانُ ‏ ‏حَتَّى يُسْتَخْلَفَ قُلْنَا مِنْ أَيْنَ تَعْلَمُ ذَلِكَ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏رَأَيْتُ اللَّيْلَةَ فِي الْمَنَامِ كَأَنَّهُ ثَلَاثَةٌ مِنْ أَصْحَابِي وُزِنُوا فَوُزِنَ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَوَزَنَ ثُمَّ وُزِنَ ‏ ‏عُمَرُ ‏ ‏فَوَزَنَ ثُمَّ وُزِنَ ‏ ‏عُثْمَانُ ‏ ‏فَنَقَصَ صَاحِبُنَا وَهُوَ صَالِحٌ ‏","","",""],[16010,16010,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏مُهَاجِرٍ أَبِي الْحَسَنِ ‏ ‏عَنْ ‏ ‏شَيْخٍ ‏ ‏أَدْرَكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏خَرَجْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ ‏ ‏فَمَرَّ بِرَجُلٍ يَقْرَأُ ‏ ‏قُلْ يَا أَيُّهَا الْكَافِرُونَ ‏ ‏قَالَ أَمَّا هَذَا فَقَدْ بَرِئَ مِنْ الشِّرْكِ قَالَ وَإِذَا آخَرُ يَقْرَأُ ‏ ‏قُلْ هُوَ اللَّهُ أَحَدٌ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِهَا وَجَبَتْ لَهُ الْجَنَّةُ ‏","","",""],[16011,16011,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏وَأَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ هِشَامٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏حُمْرَانَ بْنِ أَعْيَنَ ‏ ‏عَنْ ‏ ‏أَبِي الطُّفَيْلِ ‏ ‏عَنْ ‏ ‏فُلَانِ بْنِ جَارِيَةَ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَخَاكُمْ ‏ ‏النَّجَاشِيَّ ‏ ‏قَدْ مَاتَ فَصَلُّوا عَلَيْهِ ‏","","",""],[16012,16012,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ الْحَنَفِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنِ ‏ ‏ابْنَةِ كَرْدَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهَا ‏ ‏أَنَّهُ ‏ ‏سَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنِّي ‏ ‏نَذَرْتُ ‏ ‏أَنْ أَنْحَرَ ثَلَاثَةً مِنْ إِبِلِي فَقَالَ ‏ ‏إِنْ كَانَ عَلَى ‏ ‏جَمْعٍ ‏ ‏مِنْ ‏ ‏جَمْعِ ‏ ‏الْجَاهِلِيَّةِ أَوْ عَلَى عِيدٍ مِنْ أَعْيَادِ الْجَاهِلِيَّةِ أَوْ عَلَى وَثَنٍ فَلَا وَإِنْ كَانَ عَلَى غَيْرِ ذَلِكَ فَاقْضِ ‏ ‏نَذْرَكَ ‏ ‏قَالَ يَا رَسُولَ اللَّهِ إِنَّ عَلَى أُمِّ هَذِهِ الْجَارِيَةِ مَشْيًا ‏ ‏أَفَأَمْشِي عَنْهَا قَالَ نَعَمْ ‏","","",""],[16013,16013,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ عَبْدِ الْعَزِيزِ التَّنُوخِيِّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَوْلًى لِيَزِيدَ بْنِ نِمْرَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ نِمْرَانَ ‏ ‏قَالَ ‏ ‏لَقِيتُ ‏ ‏رَجُلًا ‏ ‏مُقْعَدًا ‏ ‏شَوَّالًا ‏ ‏فَسَأَلْتُهُ قَالَ مَرَرْتُ بَيْنَ يَدَيْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏أَتَانٍ ‏ ‏أَوْ حِمَارٍ ‏ ‏فَقَالَ ‏ ‏قَطَعَ عَلَيْنَا صَلَاتَنَا قَطَعَ اللَّهُ ‏ ‏أَثَرَهُ ‏ ‏فَأُقْعِدَ ‏","","",""],[16014,16014,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ يَعْنِي شَيْبَانَ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏شَهْرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الْأَنْصَارِيُّ ‏ ‏صَاحِبُ ‏ ‏بُدْنِ ‏ ‏النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا بَعَثَهُ قَالَ رَجَعْتُ فَقُلْتُ نَعَمْ يَا رَسُولَ اللَّهِ مَا تَأْمُرُنِي بِمَا ‏ ‏عَطِبَ ‏ ‏مِنْهَا قَالَ ‏ ‏انْحَرْهَا ثُمَّ اصْبُغْ نَعْلَهَا فِي دَمِهَا ثُمَّ ضَعْهَا عَلَى صَفْحَتِهَا ‏ ‏أَوْ عَلَى جَنْبِهَا ‏ ‏وَلَا تَأْكُلْ مِنْهَا أَنْتَ وَلَا أَحَدٌ مِنْ أَهْلِ رُفْقَتِكَ ‏","","",""],[16015,16015,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ سُحَيْمٍ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏ابْنَةِ أَبِي الْحَكَمِ الْغِفَارِيِّ ‏ ‏قَالَتْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ الرَّجُلَ ‏ ‏لَيَدْنُو مِنْ الْجَنَّةِ حَتَّى يَكُونَ مَا بَيْنَهُ وَبَيْنَهَا قِيدُ ذِرَاعٍ فَيَتَكَلَّمُ بِالْكَلِمَةِ فَيَتَبَاعَدُ مِنْهَا أَبْعَدَ مِنْ ‏ ‏صَنْعَاءَ ‏","","",""],[16016,16016,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُعَاذٍ الْأَشْهَلِيِّ ‏ ‏عَنْ ‏ ‏جَدَّتِهِ ‏ ‏أَنَّها قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا نِسَاءَ الْمُؤْمِنَاتِ ‏ ‏لَا تَحْقِرَنَّ إِحْدَاكُنَّ لِجَارَتِهَا وَلَوْ ‏ ‏كُرَاعُ ‏ ‏شَاةٍ مُحْرَقٌ ‏","","",""],[16017,16017,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏وَعَبْدُ الرَّزَّاقِ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏حَسَنُ بْنُ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏أَدْرَكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّمَا الطَّوَافُ صَلَاةٌ فَإِذَا طُفْتُمْ فَأَقِلُّوا الْكَلَامَ ‏ ‏وَلَمْ يَرْفَعْهُ ‏ ‏ابْنُ بَكْرٍ ‏","","",""],[16018,16018,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنِ ‏ ‏الْأَشْعَثِ بْنِ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏بَنِي يَرْبُوعٍ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَمِعْتُهُ وَهُوَ يُكَلِّمُ النَّاسَ يَقُولُ ‏ ‏يَدُ الْمُعْطِي الْعُلْيَا أُمَّكَ وَأَبَاكَ ‏ ‏وَأُخْتَكَ وَأَخَاكَ ثُمَّ أَدْنَاكَ فَأَدْنَاكَ قَالَ فَقَالَ رَجُلٌ يَا رَسُولَ اللَّهِ هَؤُلَاءِ ‏ ‏بَنُو ثَعْلَبَةَ ‏ ‏الَّذِينَ أَصَابُوا فُلَانًا قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا لَا ‏ ‏تَجْنِي نَفْسٌ عَلَى أُخْرَى ‏","","",""],[16019,16019,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنِ ‏ ‏الْأَزْرَقِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ يَعْمَرَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوَّلُ مَا يُحَاسَبُ بِهِ الْعَبْدُ صَلَاتُهُ فَإِنْ كَانَ أَتَمَّهَا كُتِبَتْ لَهُ تَامَّةً وَإِنْ لَمْ يَكُنْ أَتَمَّهَا قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏انْظُرُوا هَلْ تَجِدُونَ لِعَبْدِي مِنْ تَطَوُّعٍ فَتُكْمِلُوا بِهَا فَرِيضَتَهُ ثُمَّ الزَّكَاةُ كَذَلِكَ ثُمَّ تُؤْخَذُ الْأَعْمَالُ عَلَى حَسَبِ ذَلِكَ ‏","","",""],[16020,16020,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْمُهَلَّبِ بْنِ أَبِي صُفْرَةَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا ‏ ‏أُرَاهُمْ اللَّيْلَةَ إِلَّا ‏ ‏سَيُبَيِّتُونَكُمْ ‏ ‏فَإِنْ فَعَلُوا فَشِعَارُكُمْ ‏ ‏حم لَا يُنْصَرُونَ ‏","","",""],[16021,16021,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ فُضَيْلٍ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏عَنْ ‏ ‏أَبِي تَمِيمَةَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ قَوْمِهِ ‏ ‏أَنَّهُ أَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ قَالَ شَهِدْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَتَاهُ رَجُلٌ فَقَالَ أَنْتَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ قَالَ أَنْتَ ‏ ‏مُحَمَّدٌ ‏ ‏فَقَالَ نَعَمْ قَالَ ‏ ‏فَإِلَامَ تَدْعُو قَالَ ‏ ‏أَدْعُو إِلَى اللَّهِ عَزَّ وَجَلَّ وَحْدَهُ مَنْ إِذَا كَانَ بِكَ ضُرٌّ فَدَعَوْتَهُ كَشَفَهُ عَنْكَ وَمَنْ إِذَا أَصَابَكَ عَامُ سَنَةٍ فَدَعَوْتَهُ أَنْبَتَ لَكَ وَمَنْ إِذَا كُنْتَ فِي أَرْضٍ ‏ ‏قَفْرٍ ‏ ‏فَأَضْلَلْتَ فَدَعَوْتَهُ رَدَّ عَلَيْكَ قَالَ فَأَسْلَمَ الرَّجُلُ ثُمَّ قَالَ أَوْصِنِي يَا رَسُولَ اللَّهِ قَالَ لَهُ لَا تَسُبَّنَّ شَيْئًا ‏ ‏أَوْ قَالَ أَحَدًا شَكَّ ‏ ‏الْحَكَمُ ‏ ‏قَالَ فَمَا سَبَبْتُ بَعِيرًا وَلَا شَاةً مُنْذُ أَوْصَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَا تَزْهَدْ فِي الْمَعْرُوفِ وَلَوْ مُنْبَسِطٌ وَجْهُكَ إِلَى أَخِيكَ وَأَنْتَ تُكَلِّمُهُ ‏ ‏وَأَفْرِغْ مِنْ دَلْوِكَ فِي إِنَاءِ الْمُسْتَسْقِي ‏ ‏وَاتَّزِرْ ‏ ‏إِلَى نِصْفِ السَّاقِ فَإِنْ أَبَيْتَ فَإِلَى الْكَعْبَيْنِ وَإِيَّاكَ ‏ ‏وَإِسْبَالَ ‏ ‏الْإِزَارِ ‏ ‏فَإِنَّهَا مِنْ ‏ ‏الْمَخِيلَةِ ‏ ‏وَاللَّهُ تَبَارَكَ وَتَعَالَى لَا يُحِبُّ ‏ ‏الْمَخِيلَةَ ‏","","",""],[16022,16022,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏مُهَاجِرٍ الصَّائِغِ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏لَمْ يُسَمِّهِ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَجُلًا ‏ ‏يَعْنِي النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ ‏ ‏قُلْ يَا أَيُّهَا الْكَافِرُونَ ‏ ‏قَالَ أَمَّا هَذَا فَقَدْ بَرِئَ مِنْ الشِّرْكِ وَسَمِعَ آخَرَ يَقْرَأُ ‏ ‏قُلْ هُوَ اللَّهُ أَحَدٌ ‏ ‏فَقَالَ أَمَّا هَذَا فَقَدْ غُفِرَ لَهُ ‏","","",""],[16023,16023,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏بَعْضِ أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كَوَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَعْدًا ‏ ‏أَوْ ‏ ‏أَسْعَدَ بْنَ زُرَارَةَ ‏ ‏فِي حَلْقِهِ مِنْ ‏ ‏الذُّبْحَةِ ‏ ‏وَقَالَ لَا أَدَعُ فِي نَفْسِي حَرَجًا مِنْ ‏ ‏سَعْدٍ ‏ ‏أَوْ ‏ ‏أَسْعَدَ بْنِ زُرَارَةَ ‏","","",""],[16024,16024,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي جَعْفَرٍ ‏ ‏عَنْ ‏ ‏الْفَضْلِ بْنِ عَمْرِو بْنِ أُمَيَّةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏رِجَالًا ‏ ‏يَتَحَدَّثُونَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِذَا أُعْتِقَتْ الْأَمَةُ فَهِيَ ‏ ‏بِالْخِيَارِ ‏ ‏مَا لَمْ ‏ ‏يَطَأْهَا ‏ ‏إِنْ شَاءَتْ فَارَقَتْهُ وَإِنْ ‏ ‏وَطِئَهَا ‏ ‏فَلَا ‏ ‏خِيَارَ ‏ ‏لَهَا وَلَا تَسْتَطِيعُ فِرَاقَهُ ‏","","",""],[16025,16025,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ أَبِي جَعْفَرٍ ‏ ‏عَنِ ‏ ‏الْفَضْلِ بْنِ الْحَسَنِ بْنِ عَمْرِو بْنِ أُمَيَّةَ الضَّمْرِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏رِجَالًا ‏ ‏مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَحَدَّثُونَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أُعْتِقَتْ الْأَمَةُ وَهِيَ تَحْتَ الْعَبْدِ فَأَمْرُهَا بِيَدِهَا فَإِنْ هِيَ أَقَرَّتْ حَتَّى ‏ ‏يَطَأَهَا ‏ ‏فَهِيَ امْرَأَتُهُ لَا تَسْتَطِيعُ فِرَاقَهُ ‏","","",""],[16026,16026,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرُ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ يَزِيدَ يَعْنِي ابْنَ جَابِرٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ اللَّجْلَاجِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَائِشٍ ‏ ‏عَنْ ‏ ‏بَعْضِ أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ عَلَيْهِمْ ذَاتَ ‏ ‏غَدَاةٍ ‏ ‏وَهُوَ طَيِّبُ النَّفْسِ مُسْفِرُ الْوَجْهِ ‏ ‏أَوْ مُشْرِقُ الْوَجْهِ ‏ ‏قُلْنَا يَا رَسُولَ اللَّهِ إِنَّا نَرَاكَ طَيِّبَ النَّفْسِ مُسْفِرَ الْوَجْهِ ‏ ‏أَوْ مُشْرِقَ الْوَجْهِ ‏ ‏فَقَالَ وَمَا يَمْنَعُنِي وَأَتَانِي رَبِّي عَزَّ وَجَلَّ اللَّيْلَةَ فِي أَحْسَنِ صُورَةٍ قَالَ ‏ ‏يَا ‏ ‏مُحَمَّدُ ‏ ‏قُلْتُ لَبَّيْكَ رَبِّي وَسَعْدَيْكَ قَالَ فِيمَ يَخْتَصِمُ ‏ ‏الْمَلَأُ ‏ ‏الْأَعْلَى قُلْتُ لَا أَدْرِي أَيْ رَبِّ قَالَ ذَلِكَ مَرَّتَيْنِ ‏ ‏أَوْ ثَلَاثًا ‏ ‏قَالَ فَوَضَعَ كَفَّيْهِ بَيْنَ كَتِفَيَّ فَوَجَدْتُ بَرْدَهَا بَيْنَ ثَدْيَيَّ حَتَّى تَجَلَّى لِي مَا فِي السَّمَوَاتِ وَمَا فِي الْأَرْضِ ثُمَّ تَلَا هَذِهِ الْآيَةَ ‏ { ‏وَكَذَلِكَ ‏ ‏نُرِي ‏ ‏إِبْرَاهِيمَ ‏ ‏مَلَكُوتَ السَّمَوَاتِ وَالْأَرْضِ وَلِيَكُونَ مِنْ الْمُوقِنِينَ ‏} ‏ثُمَّ قَالَ يَا ‏ ‏مُحَمَّدُ ‏ ‏فِيمَ يَخْتَصِمُ ‏ ‏الْمَلَأُ ‏ ‏الْأَعْلَى قَالَ قُلْتُ فِي الْكَفَّارَاتِ قَالَ وَمَا الْكَفَّارَاتُ قُلْتُ الْمَشْيُ عَلَى الْأَقْدَامِ إِلَى الْجَمَاعَاتِ وَالْجُلُوسُ فِي الْمَسْجِدِ خِلَافَ الصَّلَوَاتِ وَإِبْلَاغُ الْوُضُوءِ فِي ‏ ‏الْمَكَارِهِ ‏ ‏قَالَ مَنْ فَعَلَ ذَلِكَ عَاشَ بِخَيْرٍ وَمَاتَ بِخَيْرٍ وَكَانَ مِنْ خَطِيئَتِهِ كَيَوْمِ وَلَدَتْهُ أُمُّهُ وَمِنْ الدَّرَجَاتِ طِيبُ الْكَلَامِ وَبَذْلُ السَّلَامِ وَإِطْعَامُ الطَّعَامِ وَالصَّلَاةُ بِاللَّيْلِ وَالنَّاسُ نِيَامٌ قَالَ يَا ‏ ‏مُحَمَّدُ ‏ ‏إِذَا صَلَّيْتَ فَقُلْ اللَّهُمَّ إِنِّي أَسْأَلُكَ الطَّيِّبَاتِ وَتَرْكَ الْمُنْكَرَاتِ وَحُبَّ الْمَسَاكِينِ وَأَنْ تَتُوبَ عَلَيَّ وَإِذَا أَرَدْتَ ‏ ‏فِتْنَةً ‏ ‏فِي النَّاسِ فَتَوَفَّنِي غَيْرَ ‏ ‏مَفْتُونٍ ‏","","",""],[16027,16027,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏الزُّبَيْرِيُّ مُحَمَّدُ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ الْعَزِيزِ بْنُ عَبْدِ اللَّهِ بْنِ عَامِرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَنْ سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَمَرَ بِرَجْمِ رَجُلٍ بَيْنَ ‏ ‏مَكَّةَ ‏ ‏وَالْمَدِينَةِ ‏ ‏فَلَمَّا وَجَدَ مَسَّ الْحِجَارَةِ خَرَجَ فَهَرَبَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَهَلَّا تَرَكْتُمُوهُ ‏","","",""],[16028,16028,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ مَتَى جُعِلْتَ نَبِيًّا قَالَ ‏ ‏وَآدَمُ ‏ ‏بَيْنَ الرُّوحِ وَالْجَسَدِ ‏","","",""],[16029,16029,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْمُبَارَكُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْحَسَنُ ‏ ‏أَنَّ ‏ ‏شَيْخًا ‏ ‏مِنْ ‏ ‏بَنِي سَلِيطٍ ‏ ‏أَخْبَرَهُ قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُكَلِّمُهُ فِي ‏ ‏سَبْيٍ ‏ ‏أُصِيبَ لَنَا فِي الْجَاهِلِيَّةِ فَإِذَا هُوَ قَاعِدٌ وَعَلَيْهِ حَلْقَةٌ قَدْ أَطَافَتْ بِهِ وَهُوَ يُحَدِّثُ الْقَوْمَ عَلَيْهِ ‏ ‏إِزَارُ ‏ ‏قِطْرٍ ‏ ‏لَهُ غَلِيظٌ قَالَ سَمِعْتُهُ يَقُولُ وَهُوَ يُشِيرُ بِإِصْبَعِهِ ‏ ‏الْمُسْلِمُ أَخُو الْمُسْلِمِ لَا يَظْلِمُهُ وَلَا يَخْذُلُهُ التَّقْوَى هَاهُنَا التَّقْوَى هَاهُنَا يَقُولُ أَيْ فِي الْقَلْبِ ‏","","",""],[16030,16030,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ سَعْدٍ أَبُو دَاوُدَ الْحَفَرِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا بْنِ أَبِي زَائِدَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعْدُ بْنُ طَارِقٍ ‏ ‏عَنْ ‏ ‏بِلَالِ بْنِ يَحْيَى ‏ ‏عَنْ ‏ ‏عِمْرَانَ بْنِ حُصَيْنٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَعْرَابِيٌّ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا أَخَافُ عَلَى ‏ ‏قُرَيْشٍ ‏ ‏إِلَّا أَنْفُسَهَا قُلْتُ مَا لَهُمْ قَالَ ‏ ‏أَشِحَّةٌ ‏ ‏بَجَرَةٌ ‏ ‏وَإِنْ طَالَ بِكَ عُمْرٌ لَتَنْظُرَنَّ ‏ ‏إِلَيْهِمْ ‏ ‏يَفْتِنُونَ ‏ ‏النَّاسَ حَتَّى ‏ ‏تَرَى النَّاسَ بَيْنَهُمْ كَالْغَنَمِ بَيْنَ الْحَوْضَيْنِ إِلَى هَذَا مَرَّةً وَإِلَى هَذَا مَرَّةً ‏","","",""],[16031,16031,"","","‏ ‏حَدَّثَنَا ‏ ‏الزُّبَيْرِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏مَعْبَدِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَيْرٍ ‏ ‏أَوْ ‏ ‏عَمِيرَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏زَوْجُ ابْنَةِ أَبِي لَهَبٍ ‏ ‏قَالَ ‏ ‏دَخَلَ عَلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ تَزَوَّجْتُ ‏ ‏ابْنَةَ أَبِي لَهَبٍ ‏ ‏فَقَالَ هَلْ مِنْ لَهْوٍ ‏","","",""],[16032,16032,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَلِيٌّ ‏ ‏عَنْ ‏ ‏يَحْيَى يَعْنِي ابْنَ أَبِي كَثِيرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏حَيَّةُ التَّمِيمِيُّ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏أَخْبَرَهُ أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا شَيْءَ فِي ‏ ‏الْهَامِ ‏ ‏وَالْعَيْنُ ‏ ‏حَقٌّ وَأَصْدَقُ ‏ ‏الطِّيَرِ الْفَأْلُ ‏","","",""],[16033,16033,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏وَعَبْدُ الصَّمَدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي جَعْفَرٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏بَعْضِ أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بَيْنَمَا رَجُلٌ ‏ ‏يُصَلِّي وَهُوَ ‏ ‏مُسْبِلٌ ‏ ‏إِزَارَهُ ‏ ‏إِذْ قَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اذْهَبْ فَتَوَضَّأْ قَالَ فَذَهَبَ فَتَوَضَّأَ ثُمَّ جَاءَ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اذْهَبْ فَتَوَضَّأْ قَالَ فَذَهَبَ فَتَوَضَّأَ ثُمَّ جَاءَ فَقَالَ مَا لَكَ يَا رَسُولَ اللَّهِ مَا لَكَ أَمَرْتَهُ يَتَوَضَّأُ ثُمَّ سَكَتَّ قَالَ إِنَّهُ كَانَ ‏ ‏يُصَلِّي وَهُوَ ‏ ‏مُسْبِلٌ ‏ ‏إِزَارَهُ ‏ ‏وَإِنَّ اللَّهَ عَزَّ وَجَلَّ لَا يَقْبَلُ صَلَاةَ عَبْدٍ ‏ ‏مُسْبِلٍ ‏ ‏إِزَارَهُ ‏","","",""],[16034,16034,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ مُحَمَّدٍ النَّاقِدُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُبَيْدَةُ بْنُ حُمَيْدٍ الضَّبِّيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏ذِي الْغُرَّةِ ‏ ‏قَالَ ‏ ‏عَرَضَ أَعْرَابِيٌّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسِيرُ فَقَالَ يَا رَسُولَ اللَّهِ تُدْرِكُنَا الصَّلَاةُ وَنَحْنُ فِي ‏ ‏أَعْطَانِ ‏ ‏الْإِبِلِ ‏ ‏أَفَنُصَلِّي فِيهَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا قَالَ أَفَنَتَوَضَّأُ مِنْ لُحُومِهَا قَالَ نَعَمْ قَالَ ‏ ‏أَفَنُصَلِّي فِي ‏ ‏مَرَابِضِ ‏ ‏الْغَنَمِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَعَمْ قَالَ أَفَنَتَوَضَّأُ مِنْ لُحُومِهَا قَالَ لَا ‏","","",""],[16035,16035,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ مَعِينٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عُبَيْدَةَ يَعْنِي الْحَدَّادَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي مَنْصُورٍ ‏ ‏عَنْ ‏ ‏ذِي اللِّحْيَةِ الْكِلَابِيِّ ‏ ‏أَنَّهُ قَالَ ‏ ‏يَا رَسُولَ اللَّهِ أَنَعْمَلُ فِي أَمْرٍ مُسْتَأْنَفٍ أَوْ أَمْرٍ قَدْ فُرِغَ مِنْهُ قَالَ لَا بَلْ فِي أَمْرٍ قَدْ فُرِغَ مِنْهُ قَالَ ‏ ‏فَفِيمَ نَعْمَلُ إِذًا قَالَ اعْمَلُوا فَكُلٌّ مُيَسَّرٌ لِمَا خُلِقَ لَهُ ‏","","",""],[16036,16036,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ اللَّهِ الْبَصْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سَهْلُ بْنُ أَسْلَمَ الْعَدَوِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي مَنْصُورٍ ‏ ‏عَنْ ‏ ‏ذِي اللِّحْيَةِ الْكِلَابِيِّ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ أَنَعْمَلُ فِي أَمْرٍ مُسْتَأْنَفٍ أَوْ فِي أَمْرٍ قَدْ فُرِغَ مِنْهُ قَالَ بَلْ فِي أَمْرٍ قَدْ فُرِغَ مِنْهُ قَالَ فَفِيمَ الْعَمَلُ فَقَالَ ‏ ‏اعْمَلُوا فَكُلٌّ مُيَسَّرٌ لِمَا خُلِقَ لَهُ ‏","","",""],[16037,16037,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو صَالِحٍ الْحَكَمُ بْنُ مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ضَمْرَةُ بْنُ رَبِيعَةَ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي عِمْرَانَ ‏ ‏عَنْ ‏ ‏ذِي الْأَصَابِعِ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏إِنْ ابْتُلِينَا بَعْدَكَ بِالْبَقَاءِ أَيْنَ تَأْمُرُنَا قَالَ عَلَيْكَ ‏ ‏بِبَيْتِ الْمَقْدِسِ ‏ ‏فَلَعَلَّهُ أَنْ يَنْشَأَ لَكَ ذُرِّيَّةٌ ‏ ‏يَغْدُونَ ‏ ‏إِلَى ذَلِكَ ‏ ‏الْمَسْجِدِ ‏ ‏وَيَرُوحُونَ ‏","","",""],[16038,16038,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو صَالِحٍ الْحَكَمُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏عِيسَى بْنُ يُونُسَ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏أَخْبَرَنَا عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏ذِي الْجَوْشَنِ الضِّبَابِيِّ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْدَ أَنْ فَرَغَ مِنْ أَهْلِ ‏ ‏بَدْرٍ ‏ ‏بِابْنِ فَرَسٍ لِي يُقَالُ لَهَا ‏ ‏الْقَرْحَاءُ ‏ ‏فَقُلْتُ يَا ‏ ‏مُحَمَّدُ ‏ ‏إِنِّي قَدْ جِئْتُكَ بِابْنِ الْقَرْحَاءِ لِتَتَّخِذَهُ قَالَ ‏ ‏لَا حَاجَةَ لِي فِيهِ وَإِنْ أَرَدْتَ أَنْ ‏ ‏أَقِيضَكَ ‏ ‏فِيهَا ‏ ‏الْمُخْتَارَةَ ‏ ‏مِنْ دُرُوعِ ‏ ‏بَدْرٍ ‏ ‏فَعَلْتُ فَقُلْتُ مَا كُنْتُ ‏ ‏لِأَقِيضَهُ ‏ ‏الْيَوْمَ بِعُدَّةٍ قَالَ لَا حَاجَةَ لِي فِيهِ ثُمَّ قَالَ يَا ‏ ‏ذَا الْجَوْشَنِ ‏ ‏أَلَا تُسْلِمُ فَتَكُونَ مِنْ أَوَّلِ أَهْلِ هَذَا الْأَمْرِ فَقُلْتُ لَا قَالَ لِمَ قُلْتُ إِنِّي رَأَيْتُ قَوْمَكَ ‏ ‏وَلِعُوا ‏ ‏بِكَ قَالَ فَكَيْفَ بَلَغَكَ عَنْ مَصَارِعِهِمْ ‏ ‏بِبَدْرٍ ‏ ‏قُلْتُ قَدْ بَلَغَنِي قَالَ فَإِنَّا ‏ ‏نُهْدِي لَكَ قُلْتُ إِنْ تَغْلِبْ عَلَى ‏ ‏الْكَعْبَةِ ‏ ‏وَتَقْطُنْهَا ‏ ‏قَالَ لَعَلَّكَ إِنْ عِشْتَ ‏ ‏تَرَى ذَلِكَ ثُمَّ قَالَ يَا ‏ ‏بِلَالُ ‏ ‏خُذْ حَقِيبَةَ الرَّجُلِ فَزَوِّدْهُ مِنْ الْعَجْوَةِ فَلَمَّا ‏ ‏أَدْبَرْتُ ‏ ‏قَالَ أَمَا إِنَّهُ مِنْ خَيْرِ فُرْسَانِ ‏ ‏بَنِي عَامِرٍ ‏ ‏قَالَ فَوَاللَّهِ إِنِّي بِأَهْلِي ‏ ‏بِالْغَوْرِ ‏ ‏إِذْ أَقْبَلَ رَاكِبٌ فَقُلْتُ مَا فَعَلَ النَّاسُ قَالَ وَاللَّهِ قَدْ غَلَبَ ‏ ‏مُحَمَّدٌ ‏ ‏عَلَى ‏ ‏الْكَعْبَةِ ‏ ‏وَقَطَنَهَا ‏ ‏فَقُلْتُ ‏ ‏هَبِلَتْنِي ‏ ‏أُمِّي وَلَوْ أُسْلِمُ يَوْمَئِذٍ ثُمَّ أَسْأَلُهُ ‏ ‏الْحِيرَةَ ‏ ‏لَأَقْطَعَنِيهَا ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ بْنُ أَبِي شَيْبَةَ أَبُو مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَرِيرٌ يَعْنِي ابْنَ حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ الْهَمْدَانِيِّ ‏ ‏قَالَ ‏ ‏قَدِمَ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذُو الْجَوْشَنِ ‏ ‏وَأَهْدَى لَهُ فَرَسًا وَهُوَ يَوْمَئِذٍ مُشْرِكٌ فَأَبَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَقْبَلَهُ ثُمَّ قَالَ إِنْ شِئْتَ بِعْتَنِيهِ ‏ ‏أَوْ هَلْ لَكَ أَنْ تَبِيعَنِيهِ ‏ ‏بِالْمُتَخَيَّرَةِ ‏ ‏مِنْ دُرُوعِ ‏ ‏بَدْرٍ ‏ ‏ثُمَّ قَالَ لَهُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلْ لَكَ أَنْ تَكُونَ أَوَّلَ مَنْ يَدْخُلُ فِي هَذَا الْأَمْرِ فَقَالَ لَا فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا يَمْنَعُكَ مِنْ ذَلِكَ قَالَ رَأَيْتُ قَوْمَكَ قَدْ كَذَّبُوكَ وَأَخْرَجُوكَ وَقَاتَلُوكَ فَانْظُرْ مَا تَصْنَعُ فَإِنْ ‏ ‏ظَهَرْتَ ‏ ‏عَلَيْهِمْ آمَنْتُ بِكَ وَاتَّبَعْتُكَ وَإِنْ ‏ ‏ظَهَرُوا ‏ ‏عَلَيْكَ لَمْ أَتَّبِعْكَ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏ذَا الْجَوْشَنِ ‏ ‏لَعَلَّكَ إِنْ بَقِيتَ وَذَكَرَ الْحَدِيثَ نَحْوًا مِنْهُ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عِيسَى بْنُ يُونُسَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَنْ ‏ ‏ذِي الْجَوْشَنِ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْدَ أَنْ فَرَغَ مِنْ ‏ ‏بَدْرٍ ‏ ‏بِابْنِ فَرَسٍ لِي يُقَالُ لَهَا الْقَرْحَاءُ فَقُلْتُ يَا ‏ ‏مُحَمَّدُ ‏ ‏وَذَكَرَ الْحَدِيثَ ‏","","",""],[16039,16039,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَنْصُورِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏أُمِّ عُثْمَانَ ابْنَةِ سُفْيَانَ ‏ ‏وَهِيَ أُمُّ ‏ ‏بَنِي شَيْبَةَ الْأَكَابِرِ ‏ ‏قَالَ ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏وَقَدْ بَايَعَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعَا ‏ ‏شَيْبَةَ ‏ ‏فَفَتَحَ فَلَمَّا دَخَلَ ‏ ‏الْبَيْتَ ‏ ‏وَرَجَعَ وَفَرَغَ وَرَجَعَ ‏ ‏شَيْبَةُ ‏ ‏إِذَا رَسُولُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ أَجِبْ فَأَتَاهُ فَقَالَ إِنِّي رَأَيْتُ فِي ‏ ‏الْبَيْتِ ‏ ‏قَرْنًا فَغَيِّبْهُ ‏ ‏قَالَ ‏ ‏مَنْصُورٌ ‏ ‏فَحَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ مُسَافِعٍ ‏ ‏عَنْ ‏ ‏أُمِّي ‏ ‏عَنْ ‏ ‏أُمِّ عُثْمَانَ بِنْتِ سُفْيَانَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهُ فِي الْحَدِيثِ ‏ ‏فَإِنَّهُ لَا يَنْبَغِي أَنْ يَكُونَ فِي ‏ ‏الْبَيْتِ ‏ ‏شَيْءٌ ‏ ‏يُلْهِي الْمُصَلِّينَ ‏","","",""],[16040,16040,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏خَالِهِ ‏ ‏مُسَافِعٍ ‏ ‏عَنْ ‏ ‏صَفِيَّةَ بِنْتِ شَيْبَةَ ‏ ‏أُمِّ ‏ ‏مَنْصُورٍ ‏ ‏قَالَتْ أَخْبَرَتْنِي ‏ ‏امْرَأَةٌ ‏ ‏مِنْ ‏ ‏بَنِي سُلَيْمٍ ‏ ‏وَلَدَتْ عَامَّةَ أَهْلِ دَارِنَا ‏ ‏أَرْسَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏عُثْمَانَ بْنِ طَلْحَةَ ‏ ‏وَقَالَ مَرَّةً إِنَّهَا سَأَلَتْ ‏ ‏عُثْمَانَ بْنَ طَلْحَةَ ‏ ‏لِمَ دَعَاكَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنِّي كُنْتُ رَأَيْتُ قَرْنَيْ الْكَبْشِ حِينَ دَخَلْتُ ‏ ‏الْبَيْتَ ‏ ‏فَنَسِيتُ أَنْ آمُرَكَ أَنْ ‏ ‏تُخَمِّرَهُمَا ‏ ‏فَخَمِّرْهُمَا ‏ ‏فَإِنَّهُ لَا يَنْبَغِي أَنْ يَكُونَ فِي ‏ ‏الْبَيْتِ ‏ ‏شَيْءٌ يَشْغَلُ الْمُصَلِّيَ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏لَمْ تَزَلْ قَرْنَا الْكَبْشِ فِي ‏ ‏الْبَيْتِ ‏ ‏حَتَّى احْتَرَقَ ‏ ‏الْبَيْتُ ‏ ‏فَاحْتَرَقَا ‏","","",""],[16041,16041,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏صَفِيَّةَ ‏ ‏عَنْ ‏ ‏بَعْضِ أَزْوَاجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَتَى عَرَّافًا فَصَدَّقَهُ بِمَا يَقُولُ لَمْ يُقْبَلْ لَهُ صَلَاةٌ أَرْبَعِينَ يَوْمًا ‏","","",""],[16042,16042,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ يَعْنِي ابْنَ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ ذَكْوَانَ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏امْرَأَةٍ ‏ ‏مِنْهُمْ ‏ ‏قَالَتْ ‏ ‏دَخَلَ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا آكُلُ بِشِمَالِي وَكُنْتُ امْرَأَةً ‏ ‏عَسْرَاءَ ‏ ‏فَضَرَبَ يَدِي فَسَقَطَتْ اللُّقْمَةُ فَقَالَ ‏ ‏لَا تَأْكُلِي بِشِمَالِكِ وَقَدْ جَعَلَ اللَّهُ تَبَارَكَ وَتَعَالَى لَكِ يَمِينًا ‏ ‏أَوْ قَالَ قَدْ أَطْلَقَ اللَّهُ عَزَّ وَجَلَّ لَكِ يَمِينَكِ ‏ ‏قَالَ ‏ ‏فَتَحَوَّلَتْ شِمَالِي يَمِينًا فَمَا أَكَلْتُ بِهَا بَعْدُ ‏","","",""],[16043,16043,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ أُمَيَّةَ ‏ ‏عَنْ ‏ ‏مَوْلًى لَهُمْ يُقَالُ لَهُ ‏ ‏مُزَاحِمُ بْنُ أَبِي مُزَاحِمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ عَبْدِ اللَّهِ بْنِ خَالِدِ بْنِ أَسِيدٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ مِنْهُمْ مِنْ ‏ ‏خُزَاعَةَ ‏ ‏يُقَالُ لَهُ ‏ ‏مُخَرِّشٌ ‏ ‏أَوْ ‏ ‏مُحَرِّشٌ ‏ ‏لَمْ يَكُنْ ‏ ‏سُفْيَانُ ‏ ‏يُقِيمُ عَلَى اسْمِهِ وَرُبَّمَا قَالَ ‏ ‏مُحَرِّسٌ ‏ ‏وَلَمْ أَسْمَعْهُ أَنَا ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ مِنْ ‏ ‏الْجِعِرَّانَةِ ‏ ‏لَيْلَةً فَاعْتَمَرَ ثُمَّ رَجَعَ وَأَصْبَحَ بِهَا كَبَائِتٍ فَنَظَرْتُ إِلَى ظَهْرِهِ كَأَنَّهُ سَبِيكَةُ فِضَّةٍ ‏","","",""],[16044,16044,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏ثَقِيفٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَالَ ‏ ‏فَنَضَحَ ‏ ‏فَرْجَهُ ‏","","",""],[16045,16045,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏حَفْصُ بنُ غِيَاثٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ أَبِي هِنْدٍ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏أَبِي جَبِيرَةَ بْنِ الضَّحَّاكِ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏عُمُومَةٍ ‏ ‏لَهُ ‏ ‏قَدِمَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَيْسَ أَحَدٌ مِنَّا إِلَّا لَهُ لَقَبٌ أَوْ لَقَبَانِ قَالَ فَكَانَ إِذَا دَعَا بِلَقَبِهِ قُلْنَا يَا رَسُولَ اللَّهِ إِنَّ هَذَا يَكْرَهُ هَذَا قَالَ فَنَزَلَتْ ‏ { ‏وَلَا تَنَابَزُوا بِالْأَلْقَابِ ‏}","","",""],[16046,16046,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي سُلَيْمَانَ ‏ ‏شَيْخٌ صَالِحٌ حَسَنُ الْهَيْئَةِ مَدِينِيٌّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ عَبْدِ اللَّهِ بْنِ خُبَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏قَالَ ‏ ‏كُنَّا فِي مَجْلِسٍ فَطَلَعَ عَلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَهُ ‏","","",""],[16047,16047,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبَّادٌ يَعْنِي ابْنَ رَاشِدٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏بَنِي سَلِيطٍ ‏ ‏أَنَّهُ ‏ ‏مَرَّ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ قَاعِدٌ عَلَى بَابِ ‏ ‏مَسْجِدِهِ ‏ ‏مُحْتَبٍ ‏ ‏وَعَلَيْهِ ثَوْبٌ لَهُ ‏ ‏قِطْرٌ ‏ ‏لَيْسَ عَلَيْهِ ثَوْبٌ غَيْرَهُ وَهُوَ يَقُولُ ‏ ‏الْمُسْلِمُ أَخُو الْمُسْلِمِ لَا يَظْلِمُهُ وَلَا يَخْذُلُهُ ثُمَّ أَشَارَ بِيَدِهِ إِلَى صَدْرِهِ يَقُولُ التَّقْوَى هَاهُنَا التَّقْوَى هَاهُنَا ‏","","",""],[16048,16048,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الرُّكَيْنُ بْنُ الرَّبِيعِ بْنِ عُمَيْلَةَ ‏ ‏عَنْ ‏ ‏أَبِي عَمْرٍو الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏عَنْ النَّبِيِّ قَالَ ‏ ‏الْخَيْلُ ثَلَاثَةٌ فَرَسٌ يَرْبِطُهُ الرَّجُلُ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ فَثَمَنُهُ أَجْرٌ وَرُكُوبُهُ أَجْرٌ ‏ ‏وَعَارِيَتُهُ ‏ ‏أَجْرٌ وَعَلَفُهُ أَجْرٌ وَفَرَسٌ ‏ ‏يُغَالِقُ ‏ ‏عَلَيْهِ الرَّجُلُ وَيُرَاهِنُ فَثَمَنُهُ ‏ ‏وِزْرٌ ‏ ‏وَعَلَفُهُ ‏ ‏وِزْرٌ ‏ ‏وَفَرَسٌ ‏ ‏لِلْبِطْنَةِ ‏ ‏فَعَسَى أَنْ يَكُونَ ‏ ‏سَدَادًا ‏ ‏مِنْ الْفَقْرِ إِنْ شَاءَ اللَّهُ تَعَالَى ‏","","",""],[16049,16049,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حُصَيْنِ بْنِ عُرْوَةَ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏جَدَّتِي ‏ ‏قَالَتْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏وَلَوْ اسْتُعْمِلَ عَلَيْكُمْ عَبْدٌ يَقُودُكُمْ بِكِتَابِ اللَّهِ عَزَّ وَجَلَّ ‏ ‏فَاسْمَعُوا لَهُ وَأَطِيعُوا ‏","","",""],[16050,16050,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ حُصَيْنٍ ‏ ‏عَنْ ‏ ‏جَدَّتِهِ ‏ ‏قَالَتْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يَرْحَمُ اللَّهُ الْمُحَلِّقِينَ يَرْحَمُ اللَّهُ الْمُحَلِّقِينَ قَالُوا فِي الثَّالِثَةِ وَالْمُقَصِّرِينَ قَالَ وَالْمُقَصِّرِينَ ‏","","",""],[16051,16051,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورِ بْنِ حَيَّانَ الْأَسَدِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ نَجَّادٍ ‏ ‏عَنْ ‏ ‏جَدَّتِهِ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رُدُّوا السَّائِلَ وَلَوْ ‏ ‏بِظِلْفٍ ‏ ‏مُحْتَرِقٍ ‏ ‏أَوْ مُحْرَقٍ ‏","","",""],[16052,16052,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏إِسْرَائِيلَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ حُصَيْنٍ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏قَالَتْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْطُبُ فِي حَجَّةِ الْوَدَاعِ يَقُولُ يَا أَيُّهَا النَّاسُ ‏ ‏اتَّقُوا اللَّهَ وَاسْمَعُوا وَأَطِيعُوا وَإِنْ أُمِّرَ عَلَيْكُمْ عَبْدٌ حَبَشِيٌّ ‏ ‏مُجَدَّعٌ ‏ ‏مَا أَقَامَ فِيكُمْ كِتَابَ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[16053,16053,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏ضَمْرَةَ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏جَدَّتِهِ ‏ ‏عَنِ ‏ ‏امْرَأَةٍ ‏ ‏مِنْ نِسَائِهِمْ ‏ ‏قَالَ وَقَدْ كَانَتْ صَلَّتْ الْقِبْلَتَيْنِ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏دَخَلَ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لِي ‏ ‏اخْتَضِبِي ‏ ‏تَتْرُكُ إِحْدَاكُنَّ ‏ ‏الْخِضَابَ ‏ ‏حَتَّى تَكُونَ يَدُهَا كَيَدِ الرَّجُلِ ‏ ‏قَالَتْ ‏ ‏فَمَا تَرَكَتْ ‏ ‏الْخِضَابَ ‏ ‏حَتَّى لَقِيَتْ اللَّهَ عَزَّ وَجَلَّ وَإِنْ كَانَتْ ‏ ‏لَتَخْتَضِبُ ‏ ‏وَإِنَّهَا لَابْنَةُ ثَمَانِينَ ‏","","",""],[16054,16054,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏الْهَيْثَمُ بْنُ خَارِجَةَ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَقَدْ ‏ ‏سَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏الْهَيْثَمِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَفْصُ بْنُ مَيْسَرَةَ ‏ ‏عَنِ ‏ ‏ابْنِ حَرْمَلَةَ ‏ ‏عَنْ ‏ ‏أَبِي ثِفَالٍ الْمُرِّيِّ ‏ ‏أَنَّهُ قَالَ سَمِعْتُ ‏ ‏رَبَاحَ بْنَ عَبْدِ الرَّحْمَنِ بْنِ حُوَيْطِبٍ ‏ ‏يَقُولُ حَدَّثَتْنِي ‏ ‏جَدَّتِي ‏ ‏أَنَّها سَمِعَتْ ‏ ‏أَبَاهَا ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا صَلَاةَ لِمَنْ لَا وُضُوءَ لَهُ وَلَا وُضُوءَ لِمَنْ لَمْ يَذْكُرْ اللَّهَ تَعَالَى وَلَا يُؤْمِنُ بِاللَّهِ مَنْ لَمْ يُؤْمِنْ بِي وَلَا يُؤْمِنُ بِي مَنْ لَا يُحِبُّ ‏ ‏الْأَنْصَارَ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ عِيَاضٍ ‏ ‏عَنْ ‏ ‏أَبِي ثِفَالٍ ‏ ‏بِهَذَا الْحَدِيثِ وَقَالَ سَمِعَتْ أَبَاهَا ‏ ‏سَعِيدَ بْنَ زَيْدٍ ‏","","",""],[16055,16055,"","","‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مَعْمَرٍ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سَيَّارٌ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ عَبْدِ اللَّهِ الْقَسْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لِجَدِّهِ ‏ ‏يَزِيدَ بْنِ أَسَدٍ ‏ ‏أَحِبَّ لِلنَّاسِ مَا تُحِبُّ لِنَفْسِكَ ‏","","",""],[16056,16056,"","","‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏عُقْبَةُ بْنُ مُكْرَمٍ الْعَمِّيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَلْمُ بْنُ قُتَيْبَةَ ‏ ‏عَنْ ‏ ‏يُونُسَ بْنِ أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ أَوْسَطَ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَسَدِ بْنِ كُرْزٍ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْمَرِيضُ ‏ ‏تَحَاتُّ ‏ ‏خَطَايَاهُ كَمَا ‏ ‏يَتَحَاتُّ ‏ ‏وَرَقُ الشَّجَرِ ‏","","",""],[16057,16057,"","","‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ الرُّزِّيُّ أَبُو جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏رَوْحُ بْنُ عَطَاءٍ بْنِ أَبِي مَيْمُونَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَيَّارٌ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏خَالِدَ بْنَ عَبْدِ اللَّهِ الْقَسْرِيَّ ‏ ‏وَهُوَ يَخْطُبُ عَلَى الْمِنْبَرِ وَهُوَ ‏ ‏يَقُولُ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏جَدِّي ‏ ‏أَنَّهُ قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتُحِبُّ الْجَنَّةَ قَالَ قُلْتُ نَعَمْ قَالَ ‏ ‏فَأَحِبَّ لِأَخِيكَ مَا تُحِبُّ لِنَفْسِكَ ‏","","",""],[16058,16058,"","","‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو الْحَسَنِ عُثْمَانُ بْنُ أَبِي شَيْبَةَ ‏ ‏بِالْكُوفَةِ ‏ ‏سَنَةَ ثَلَاثِينَ وَمِائَتَيْنِ ‏ ‏وَيَعْقُوبُ الدَّوْرَقِيُّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هُشَيْمُ بْنُ بَشِيرٍ ‏ ‏قَالَ ‏ ‏عُثْمَانُ بْنُ أَبِي شَيْبَةَ ‏ ‏أَخْبَرَنَا ‏ ‏سَيَّارٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏خَالِدَ بْنَ عَبْدِ اللَّهِ الْقَسْرِيَّ ‏ ‏عَلَى الْمِنْبَرِ ‏ ‏يَقُولُ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏جَدِّي ‏ ‏يَزِيدَ بْنِ أَسَدٍ ‏ ‏قَالَ قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏يَزِيدُ بْنَ أَسَدٍ ‏ ‏أَحِبَّ لِلنَّاسِ مَا تُحِبُّ لِنَفْسِكَ ‏","","",""],[16059,16059,"","","‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي بَكْرٍ وَهُوَ الْمُقَدَّمِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ ثَابِتٍ الْعَبْدِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الصَّعْبِ بْنِ جَثَّامَةَ ‏ ‏أَنَّهُ أَهْدَى لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَحْمَ صَيْدٍ فَلَمْ يَقْبَلْهُ فَرَأَى ذَلِكَ فِي وَجْهِ ‏ ‏الصَّعْبِ ‏ ‏فَقَالَ ‏ ‏إِنَّهُ لَمْ يَمْنَعْنَا أَنْ نَقْبَلَ مِنْكَ إِلَّا أَنَّا كُنَّا حُرُمًا ‏","","",""],[16060,16060,"","","‏ ‏قَالَ ‏ ‏وَسُئِلَ عَنْ الْخَيْلِ ‏ ‏يُوطِئُونَهَا ‏ ‏أَوْلَادَ الْمُشْرِكِينَ بِاللَّيْلِ فَقَالَ هُمْ ‏ ‏يَعْنِي مِنْ آبَائِهِمْ ‏","","",""],[16061,16061,"","","‏ ‏وَقَالَ ‏ ‏لَا ‏ ‏حِمَى ‏ ‏إِلَّا لِلَّهِ وَلِرَسُولِهِ ‏","","",""],[16062,16062,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو خَيْثَمَةَ زُهَيْرُ بْنُ حَرْبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الصَّعْبِ بْنِ جَثَّامَةَ ‏ ‏قَالَ ‏ ‏مَرَّ بِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا ‏ ‏بِالْأَبْوَاءِ ‏ ‏أَوْ ‏ ‏بِوَدَّانَ ‏ ‏فَأَهْدَيْتُ لَهُ لَحْمَ حِمَارِ وَحْشٍ وَهُوَ مُحْرِمٌ فَرَدَّهُ عَلَيَّ فَلَمَّا رَأَى فِي وَجْهِي الْكَرَاهِيَةَ قَالَ ‏ ‏لَيْسَ بِنَا رَدٌّ عَلَيْكَ وَلَكِنَّا حُرُمٌ ‏","","",""],[16063,16063,"","","‏ ‏قَالَ ‏ ‏وَسَمِعْتُهُ يَقُولُ ‏ ‏لَا ‏ ‏حِمَى ‏ ‏إِلَّا لِلَّهِ وَلِرَسُولِهِ ‏","","",""],[16064,16064,"","","‏ ‏قَالَ ‏ ‏وَسُئِلَ عَنْ أَهْلِ الدَّارِ مِنْ الْمُشْرِكِينَ ‏ ‏يُبَيَّتُونَ ‏ ‏فَيُصَابُ مِنْ نِسَائِهِمْ ‏ ‏وَذَرَارِيِّهِمْ ‏ ‏قَالَ هُمْ مِنْهُمْ ‏","","",""],[16065,16065,"","","‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏مُصْعَبٌ هُوَ الزُّبَيْرِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ عَبْدِ اللَّهِ بْنِ عَيَّاشٍ الْمَخْزُومِيُّ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ بْنِ مَسْعُودٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الصَّعْبِ بْنِ جَثَّامَةَ اللَّيْثِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَمَى ‏ ‏النَّقِيعَ ‏ ‏وَقَالَ ‏ ‏لَا ‏ ‏حِمَى ‏ ‏إِلَّا لِلَّهِ وَلِرَسُولِهِ ‏","","",""],[16066,16066,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُصْعَبُ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ بْنِ مَسْعُودٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الصَّعْبِ بْنِ جَثَّامَةَ اللَّيْثِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ أَهْدَى لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِمَارًا وَحْشِيًّا وَهُوَ ‏ ‏بِالْأَبْوَاءِ ‏ ‏أَوْ ‏ ‏بِوَدَّانَ ‏ ‏فَرَدَّهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا رَأَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا فِي وَجْهِي فَقَالَ إِنَّا ‏ ‏لَمْ نَرُدَّهُ عَلَيْكَ إِلَّا أَنَّا حُرُمٌ ‏","","",""],[16067,16067,"","","‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورُ بْنُ أَبِي مُزَاحِمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو أُوَيْسٍ عَبْدُ اللَّهِ بْنُ أُوَيْسٍ ‏ ‏سَمِعْتُ مِنْهُ فِي خِلَافَةِ ‏ ‏الْمَهْدِيِّ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الصَّعْبِ بْنِ جَثَّامَةَ ‏ ‏قَالَ ‏ ‏أَهْدَيْتُ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِمَارًا عَقِيرًا وَحْشِيًّا ‏ ‏بِوَدَّانَ ‏ ‏أَوْ قَالَ ‏ ‏بِالْأَبْوَاءِ ‏ ‏قَالَ فَرَدَّهُ عَلَيَّ فَلَمَّا رَأَى شِدَّةَ ذَلِكَ فِي وَجْهِي قَالَ ‏ ‏إِنَّمَا رَدَدْنَاهُ عَلَيْكَ لِأَنَّا حُرُمٌ ‏","","",""],[16068,16068,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ الْقَوَارِيرِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏صَالِحَ بْنَ كَيْسَانَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الصَّعْبِ بْنِ جَثَّامَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَمَا هُوَ ‏ ‏بِوَدَّانَ ‏ ‏إِذْ أَتَاهُ ‏ ‏الصَّعْبُ بْنُ جَثَّامَةَ ‏ ‏أَوْ رَجُلٌ ‏ ‏بِبَعْضِ حِمَارِ وَحْشٍ فَرَدَّهُ عَلَيْهِ فَقَالَ ‏ ‏إِنَّا حُرُمٌ لَا نَأْكُلُ الصَّيْدَ ‏","","",""],[16069,16069,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي بَكْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الصَّعْبِ بْنِ جَثَّامَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏حِمَى ‏ ‏إِلَّا لِلَّهِ وَرَسُولِهِ ‏","","",""],[16070,16070,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي بَكْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الصَّعْبِ بْنِ جَثَّامَةَ ‏ ‏قَالَ ‏ ‏قِيلَ يَا رَسُولَ اللَّهِ ‏ ‏إِنَّ خَيْلَنَا أَوْطَأَتْ أَوْلَادَ الْمُشْرِكِينَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هُمْ مِنْ آبَائِهِمْ ‏","","",""],[16071,16071,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ أَبِي بَكْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الصَّعْبِ بْنِ جَثَّامَةَ ‏ ‏قَالَ ‏ ‏أُوتِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِوَدَّانَ ‏ ‏بِحِمَارِ وَحْشٍ فَرَدَّهُ وَقَالَ ‏ ‏إِنَّا حُرُمٌ لَا نَأْكُلُ الصَّيْدَ ‏","","",""],[16072,16072,"","","‏ ‏حَدَّثَنَا ‏ ‏عَامِرُ بْنُ صَالِحٍ الزُّبَيْرِيُّ ‏ ‏سَنَةَ ثَمَانِينَ وَمِائَةٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يُونُسُ بْنُ يَزِيدَ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الصَّعْبِ بْنِ جَثَّامَةَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا ‏ ‏حِمَى ‏ ‏إِلَّا لِلَّهِ وَلِرَسُولِهِ ‏","","",""],[16073,16073,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو حُمَيْدٍ الْحِمْصِيُّ أَحْمَدُ بْنُ مُحَمَّدِ ابْنِ الْمُغِيرَةِ بْنِ سَيَارٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَيْوَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏بَقِيَّةُ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏رَاشِدِ بْنِ سَعْدٍ ‏ ‏قَالَ ‏ ‏لَمَّا فُتِحَتْ ‏ ‏إِصْطَخْرُ ‏ ‏نَادَى مُنَادٍ أَلَا إِنَّ ‏ ‏الدَّجَّالَ ‏ ‏قَدْ خَرَجَ قَالَ فَلَقِيَهُمْ ‏ ‏الصَّعْبُ بْنُ جَثَّامَةَ ‏ ‏قَالَ فَقَالَ لَوْلَا مَا تَقُولُونَ لَأَخْبَرْتُكُمْ أَنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَخْرُجُ ‏ ‏الدَّجَّالُ ‏ ‏حَتَّى يَذْهَلَ النَّاسُ عَنْ ذِكْرِهِ وَحَتَّى تَتْرُكَ الْأَئِمَّةُ ذِكْرَهُ عَلَى الْمَنَابِرِ ‏","","",""],[16074,16074,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو حُمَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ بْنُ نَجْدَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏جَعْفَرُ بْنُ الْحَارِثِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ بْنِ مَسْعُودٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الصَّعْبِ بْنِ جَثَّامَةَ اللَّيْثِيِّ ‏ ‏قَالَ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الدَّارِ مِنْ دُورِ الْمُشْرِكِينَ ‏ ‏نَغْشَاهَا ‏ ‏بَيَاتًا ‏ ‏فَكَيْفَ بِمَنْ يَكُونُ تَحْتَ ‏ ‏الْغَارَةِ ‏ ‏مِنْ الْوِلْدَانِ قَالَ هُمْ مِنْهُمْ ‏","","",""],[16075,16075,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْحَاقُ بْنُ مَنْصُورٍ الْكَوْسَجُ ‏ ‏مِنْ أَهْلِ ‏ ‏مَرْوَ ‏ ‏فِي سَنَةِ ثَمَانٍ وَعِشْرِينَ وَمِائَتَيْنِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ يَعْنِي ابْنَ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أخْبَرَهُ ‏ ‏الصَّعْبُ بْنُ جَثَّامَةَ ‏ ‏سُئِلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ أَهْلِ الدَّارِ مِنْ الْمُشْرِكِينَ ‏ ‏يُبَيَّتُونَ ‏ ‏فَيُصَابُ مِنْ نِسَائِهِمْ ‏ ‏وَذَرَارِيِّهِمْ ‏ ‏قَالَ هُمْ مِنْهُمْ ‏","","",""],[16076,16076,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْحَاقُ بْنُ مَنْصُورٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الصَّعْبِ بْنِ جَثَّامَةَ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏إِنَّا نُصِيبُ فِي ‏ ‏الْبَيَاتِ ‏ ‏مِنْ ‏ ‏ذَرَارِيِّ ‏ ‏الْمُشْرِكِينَ قَالَ هُمْ مِنْهُمْ ‏","","",""],[16077,16077,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنِي ‏ ‏إِسْحَاقُ بْنُ مَنْصُورٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ يَعْنِي ابْنَ سَعْدٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ يَعْنِي ابْنَ كَيْسَانَ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏أَنَّ ‏ ‏عُبَيْدَ اللَّهِ بْنَ عَبْدِ اللَّهِ ‏ ‏أخْبَرَهُ أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏الصَّعْبَ بْنَ جَثَّامَةَ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّهُ أَهْدَى لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِمَارَ وَحْشٍ وَهُوَ ‏ ‏بِوَدَّانَ ‏ ‏فَرَدَّهُ عَلَيْهِ قَالَ فَلَمَّا رَأَى مَا فِي وَجْهِي قَالَ إِنَّا ‏ ‏لَمْ نَرُدَّهُ عَلَيْكَ إِلَّا أَنَّا حُرُمٌ ‏","","",""],[16078,16078,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ مَنْصُورٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ يَعْنِي ابْنَ سَعْدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ يَعْنِي ابْنَ كَيْسَانَ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏أَنَّ ‏ ‏عُبَيْدَ اللَّهِ بْنَ عَبْدِ اللَّهِ ‏ ‏أخْبَرَهُ أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏أخْبَرَهُ أَنَّ ‏ ‏الصَّعْبَ بْنَ جَثَّامَةَ ‏ ‏أخْبَرَهُ ‏ ‏أَنَّهُ أَهْدَى لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِمَارَ وَحْشٍ وَهُوَ ‏ ‏بِوَدَّانَ ‏ ‏فَرَدَّهُ فَلَمَّا رَأَى مَا فِي وَجْهِي قَالَ إِنَّا ‏ ‏لَمْ نَرُدَّهُ عَلَيْكَ إِلَّا أَنَّا حُرُمٌ ‏","","",""],[16079,16079,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَخِي ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ بْنِ عُتْبَةَ بْنِ مَسْعُودٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عَبَّاسٍ ‏ ‏كَانَ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏الصَّعْبَ بْنَ جَثَّامَةَ بْنِ قَيْسٍ اللَّيْثِيَّ ‏ ‏يَقُولُ ‏ ‏أَهْدَيْتُ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِمَارَ وَحْشٍ ‏ ‏بِالْأَبْوَاءِ ‏ ‏فَرَدَّهُ عَلَيَّ فَلَمَّا عَرَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي وَجْهِي كَرَاهِيَةَ رَدِّهِ قَالَ ‏ ‏إِنَّهُ لَيْسَ بِنَا رَدٌّ عَلَيْكَ وَلَكِنَّا حُرُمٌ ‏","","",""],[16080,16080,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنِي ‏ ‏إِسْحَاقُ بْنُ مَنْصُورٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبُو الْيَمَانِ الْحَكَمُ بْنُ نَافِعٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ بْنِ عُتْبَةَ بْنِ مَسْعُودٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عَبَّاسٍ ‏ ‏أَخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏الصَّعْبَ بْنَ جَثَّامَةَ اللَّيْثِيَّ ‏ ‏وَكَانَ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُخْبِرُ أَنَّهُ ‏ ‏أَهْدَى لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِمَارَ وَحْشٍ ‏ ‏بِالْأَبْوَاءِ ‏ ‏أَوْ ‏ ‏بِوَدَّانَ ‏ ‏وَالنَّبِيُّ مُحْرِمٌ فَرَدَّهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الصَّعْبُ ‏ ‏فَلَمَّا عَرَفَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي وَجْهِي رَدَّهُ هَدِيَّتِي قَالَ ‏ ‏لَيْسَ بِنَا رَدٌّ عَلَيْكَ وَلَكِنِّي حُرُمٌ ‏","","",""],[16081,16081,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سُلَيْمَانَ بْنِ حَبِيبٍ لُوَيْنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏صَالِحِ بْنِ كَيْسَانَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الصَّعْبِ بْنِ جَثَّامَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَقْبَلَ حَتَّى إِذَا كَانَ ‏ ‏بِوَدَّانَ ‏ ‏أَهْدَى لَهُ أَعْرَابِيٌّ لَحْمَ صَيْدٍ فَرَدَّهُ وَقَالَ إِنَّا ‏ ‏لَا نَأْكُلُ الصَّيْدَ ‏","","",""],[16082,16082,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سُلَيْمَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الصَّعْبِ بْنِ جَثَّامَةَ ‏ ‏أَنَّهُ ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِحِمَارِ وَحْشٍ فَرَدَّهُ عَلَيْهِ وَقَالَ ‏ ‏إِنَّا حُرُمٌ لَا نَأْكُلُ الصَّيْدَ ‏","","",""],[16083,16083,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُسْلِمُ بْنُ خَالِدٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ بْنِ مَسْعُودٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عْنِ ‏ ‏الصَّعْبِ بْنِ جَثَّامَةَ ‏ ‏أَنَّهُ قَالَ ‏ ‏يَا رَسُولَ اللَّهِ ‏ ‏نَغْشَى الدَّارَ ‏ ‏أَوْ الدِّيَارَ ‏ ‏مِنْ الْمُشْرِكِينَ لَيْلًا مَعَهُمْ صِبْيَانُهُمْ وَنِسَاؤُهُمْ فَنَقْتُلُهُمْ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هُمْ مِنْهُمْ ‏","","",""],[16084,16084,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْقَاسِمِ بْنُ أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الزَّنْجِيِّ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏الزُّهْرِيَّ ‏ ‏صَابِغًا رَأْسَهُ بِالسَّوَادِ ‏","","",""],[16085,16085,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ مَنْصُورٍ الْكَوْسَجُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ شُمَيْلٍ يَعْنِي النَّضْرَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدٌ هُوَ ابْنُ عَمْرٍو ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الصَّعْبِ بْنِ جَثَّامَةَ اللَّيْثِيِّ ‏ ‏قَالَ ‏ ‏كَانَ يُحَدِّثُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحَادِيثَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏حِمَى ‏ ‏إِلَّا لِلَّهِ وَلِرَسُولِهِ ‏","","",""],[16086,16086,"","","‏ ‏قَالَ ‏ ‏وَأَهْدَيْتُ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِمَارَ وَحْشٍ وَهُوَ مُحْرِمٌ فَرَدَّهُ عَلَيَّ فَعَرَفَ ذَلِكَ فِي وَجْهِي فَقَالَ ‏ ‏إِنَّا لَمْ نَرُدَّهُ عَلَيْكَ إِلَّا أَنَّا حُرُمٌ ‏","","",""],[16087,16087,"","","‏ ‏وَسَأَلْتُهُ ‏ ‏عَنْ أَوْلَادِ الْمُشْرِكِينَ فَقَالَ اقْتُلْهُمْ مَعَهُمْ قَالَ وَقَدْ نَهَى عَنْهُمْ يَوْمَ ‏ ‏خَيْبَرَ ‏","","",""],[16088,16088,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ مَنْصُورٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الزُّبَيْرِ يَعْنِي الْحُمَيْدِيَّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ أَخْبَرَنِي ‏ ‏الصَّعْبُ بْنُ جَثَّامَةَ اللَّيْثِيُّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَسُئِلَ عَنْ أَهْلِ الدَّارِ مِنْ الْمُشْرِكِينَ ‏ ‏فَيُبَيَّتُونَ ‏ ‏فَيُصَابُ مِنْ نِسَائِهِمْ ‏ ‏وَذَرَارِيِّهِمْ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هُمْ مِنْهُمْ ‏","","",""],[16089,16089,"","","‏ ‏وَسَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا ‏ ‏حِمَى ‏ ‏إِلَّا لِلَّهِ وَلِرَسُولِهِ ‏","","",""],[16090,16090,"","","‏ ‏وَأَهْدَيْتُ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَحْمَ حِمَارِ وَحْشٍ وَهُوَ ‏ ‏بِالْأَبْوَاءِ ‏ ‏أَوْ ‏ ‏بِوَدَّانَ ‏ ‏فَرَدَّهُ عَلَيَّ فَلَمَّا رَأَى الْكَرَاهِيَةَ فِي وَجْهِي قَالَ إِنَّهُ ‏ ‏لَيْسَ مِنَّا رَدٌّ عَلَيْكَ وَلَكِنَّا حُرُمٌ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏فَحَدَّثَنَا ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏بِحَدِيثِ ‏ ‏الصَّعْبِ ‏ ‏هَذَا ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَبْلَ أَنْ نَلْقَاهُ فَقَالَ فِيهِ ‏ ‏هُمْ مِنْ آبَائِهِمْ ‏ ‏فَلَمَّا قَدِمَ عَلَيْنَا ‏ ‏الزُّهْرِيُّ ‏ ‏تَفَقَّدْتُهُ فَلَمْ يَقُلْ ‏ ‏وَقَالَ ‏ ‏هُمْ خَيْرٌ مِنْهُمْ ‏","","",""],[16091,16091,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ عَمْرٍو أَبُو سُلَيْمَانَ الضَّبِّيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏الصَّعْبَ بْنَ جَثَّامَةَ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏الدَّارُ مِنْ دُورِ الْمُشْرِكِينَ نُصَبِّحُهَا لِلْغَارَةِ فَنُصِيبُ الْوِلْدَانَ تَحْتَ بُطُونِ الْخَيْلِ وَلَا نَشْعُرُ فَقَالَ إِنَّهُمْ مِنْهُمْ ‏","","",""],[16092,16092,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ مَنْصُورٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ بْنِ مَسْعُودٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الصَّعْبِ بْنِ جَثَّامَةَ اللَّيْثِيِّ ‏ ‏أَنَّهُ ‏ ‏أَهْدَى لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏بِالْأَبْوَاءِ ‏ ‏أَوْ ‏ ‏بِوَدَّانَ ‏ ‏حِمَارًا وَحْشِيًّا فَرَدَّهُ عَلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا رَأَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا فِي وَجْهِي قَالَ ‏ ‏لَمْ نَرُدَّهُ عَلَيْكَ إِلَّا أَنَّا حُرُمٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏رَوْحُ بْنُ عُبَادَةَ ‏ ‏مِثْلَهُ ‏ ‏يَعْنِي ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏وَقَالَ ‏ ‏رَوْحٌ ‏ ‏وَجْهِهِ ‏","","",""],[16093,16093,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ عُيَيْنَةَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الصَّعْبِ بْنِ جَثَّامَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏حِمَى ‏ ‏إِلَّا لِلَّهِ وَرَسُولِهِ ‏","","",""],[16094,16094,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ الْهَيْثَمُ بْنُ خَارِجَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي فَرْوَةَ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏جَدَّتِهِ ‏ ‏مَيْمُونَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ سَنَّةَ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏بَدَأَ الْإِسْلَامُ غَرِيبًا ثُمَّ يَعُودُ غَرِيبًا كَمَا بَدَأَ ‏ ‏فَطُوبَى ‏ ‏لِلْغُرَبَاءِ قِيلَ يَا رَسُولَ اللَّهِ وَمَنْ الْغُرَبَاءُ قَالَ الَّذِينَ يُصْلِحُونَ إِذَا فَسَدَ النَّاسُ وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَيُحَازَنَّ ‏ ‏الْإِيمَانُ ‏ ‏إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏كَمَا ‏ ‏يَحُوزُ ‏ ‏السَّيْلُ وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَيَأْرِزَنَّ ‏ ‏الْإِسْلَامُ إِلَى مَا بَيْنَ الْمَسْجِدَيْنِ كَمَا ‏ ‏تَأْرِزُ ‏ ‏الْحَيَّةُ إِلَى جُحْرِهَا ‏","","",""],[16095,16095,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مُصْعَبُ بْنُ عَبْدِ اللَّهِ هُوَ الزُّبَيْرِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏فَائِدٍ ‏ ‏مَوْلَى ‏ ‏عَبَادِلَ ‏ ‏قَالَ ‏ ‏خَرَجْتُ مَعَ ‏ ‏إِبْرَاهِيمَ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي رَبِيعَةَ ‏ ‏فَأَرْسَلَ ‏ ‏إِبْرَاهِيمُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏إِلَى ‏ ‏ابْنِ سَعْدٍ ‏ ‏حَتَّى إِذَا كُنَّا ‏ ‏بِالْعَرْجِ ‏ ‏أَتَى ‏ ‏ابْنُ سَعْدٍ ‏ ‏وَسَعْدٌ ‏ ‏هُوَ الَّذِي دَلَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى طَرِيقِ رَكُوبِهِ فَقَالَ ‏ ‏إِبْرَاهِيمُ ‏ ‏أَخْبِرْنِي مَا حَدَّثَكَ أَبُوكَ ‏ ‏قَالَ ‏ ‏ابْنُ سَعْدٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَاهُمْ وَمَعَهُ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَكَانَتْ ‏ ‏لِأَبِي بَكْرٍ ‏ ‏عِنْدَنَا بِنْتٌ مُسْتَرْضَعَةٌ وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرَادَ ‏ ‏الِاخْتِصَارَ فِي الطَّرِيقِ إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏فَقَالَ لَهُ ‏ ‏سَعْدٌ ‏ ‏هَذَا ‏ ‏الْغَائِرُ ‏ ‏مِنْ رَكُوبَةٍ وَبِهِ لِصَّانِ مِنْ ‏ ‏أَسْلَمَ ‏ ‏يُقَالُ لَهُمَا ‏ ‏الْمُهَانَانِ ‏ ‏فَإِنْ شِئْتَ أَخَذْنَا عَلَيْهِمَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خُذْ بِنَا عَلَيْهِمَا قَالَ ‏ ‏سَعْدٌ ‏ ‏فَخَرَجْنَا حَتَّى ‏ ‏أَشْرَفْنَا ‏ ‏إِذَا أَحَدُهُمَا يَقُولُ لِصَاحِبِهِ هَذَا الْيَمَانِي فَدَعَاهُمَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَعَرَضَ عَلَيْهِمَا الْإِسْلَامَ فَأَسْلَمَا ثُمَّ سَأَلَهُمَا عَنْ أَسْمَائِهِمَا فَقَالَا نَحْنُ ‏ ‏الْمُهَانَانِ ‏ ‏فَقَالَ بَلْ أَنْتُمَا ‏ ‏الْمُكْرَمَانِ ‏ ‏وَأَمَرَهُمَا أَنْ يَقْدَمَا عَلَيْهِ ‏ ‏الْمَدِينَةَ ‏ ‏فَخَرَجْنَا حَتَّى أَتَيْنَا ظَاهِرَ ‏ ‏قُبَاءَ ‏ ‏فَتَلَقَّى ‏ ‏بَنُو عَمْرِو بْنِ عَوْفٍ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيْنَ ‏ ‏أَبُو أُمَامَةَ أَسْعَدُ بْنُ زُرَارَةَ ‏ ‏فَقَالَ ‏ ‏سَعْدُ بْنُ خَيْثَمَةَ ‏ ‏إِنَّهُ أَصَابَ قَبْلِي يَا رَسُولَ اللَّهِ أَفَلَا أُخْبِرُهُ لَكَ ثُمَّ مَضَى حَتَّى إِذَا طَلَعَ عَلَى النَّخْلِ فَإِذَا الشَّرْبُ مَمْلُوءٌ فَالْتَفَتَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَالَ يَا ‏ ‏أَبَا بَكْرٍ ‏ ‏هَذَا الْمَنْزِلُ رَأَيْتُنِي أَنْزِلُ عَلَى حِيَاضٍ كَحِيَاضِ ‏ ‏بَنِي مُدْلِجٍ ‏","","",""],[16096,16096,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنِي ‏ ‏سُرَيْجُ بْنُ يُونُسَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَرْوَانُ بْنُ مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ كَثِيرٍ الْكَاهِلِيِّ ‏ ‏عَنْ ‏ ‏مِسْوَرِ بْنِ يَزِيدَ الْأَسَدِيِّ ‏ ‏قَالَ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَتَرَكَ آيَةً فَقَالَ لَهُ رَجُلٌ يَا رَسُولَ اللَّهِ تَرَكْتَ آيَةَ كَذَا وَكَذَا قَالَ فَهَلَّا ذَكَّرْتَنِيهَا ‏","","",""],[16097,16097,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنِي ‏ ‏سُرَيْجُ بْنُ يُونُسَ ‏ ‏مِنْ كِتَابِهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ عَبَّادٍ يَعْنِي الْمُهَلَّبِيَّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُثْمَانَ بْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي رَاشِدٍ ‏ ‏مَوْلًى لِآلِ ‏ ‏مُعَاوِيَةَ ‏ ‏قَالَ ‏ ‏قَدِمْتُ ‏ ‏الشَّامَ ‏ ‏فَقِيلَ لِي فِي هَذِهِ الْكَنِيسَةِ ‏ ‏رَسُولُ قَيْصَرَ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَدَخَلْنَا الْكَنِيسَةَ فَإِذَا أَنَا بِشَيْخٍ كَبِيرٍ فَقُلْتُ لَهُ أَنْتَ رَسُولُ ‏ ‏قَيْصَرَ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ نَعَمْ قَالَ قُلْتُ حَدِّثْنِي عَنْ ذَلِكَ قَالَ إِنَّهُ لَمَّا غَزَا ‏ ‏تَبُوكَ ‏ ‏كَتَبَ إِلَى ‏ ‏قَيْصَرَ ‏ ‏كِتَابًا وَبَعَثَ بِهِ مَعَ رَجُلٍ يُقَالُ لَهُ ‏ ‏دِحْيَةُ بْنُ خَلِيفَةَ ‏ ‏فَلَمَّا قَرَأَ كِتَابَهُ وَضَعَهُ مَعَهُ عَلَى سَرِيرِهِ وَبَعَثَ إِلَى ‏ ‏بَطَارِقَتِهِ ‏ ‏وَرُءُوسِ أَصْحَابِهِ فَقَالَ إِنَّ هَذَا الرَّجُلَ قَدْ بَعَثَ إِلَيْكُمْ رَسُولًا وَكَتَبَ إِلَيْكُمْ كِتَابًا يُخَيِّرُكُمْ إِحْدَى ثَلَاثٍ إِمَّا أَنْ تَتَّبِعُوهُ عَلَى دِينِهِ أَوْ تُقِرُّوا لَهُ ‏ ‏بِخَرَاجٍ ‏ ‏يَجْرِي لَهُ عَلَيْكُمْ وَيُقِرَّكُمْ عَلَى هَيْئَتِكُمْ فِي بِلَادِكُمْ أَوْ أَنْ تُلْقُوا إِلَيْهِ بِالْحَرْبِ قَالَ ‏ ‏فَنَخَرُوا ‏ ‏نَخْرَةً ‏ ‏حَتَّى خَرَجَ بَعْضُهُمْ مِنْ ‏ ‏بَرَانِسِهِمْ ‏ ‏وَقَالُوا لَا نَتَّبِعُهُ عَلَى دِينِهِ وَنَدَعُ دِينَنَا وَدِينَ آبَائِنَا وَلَا نُقِرُّ لَهُ ‏ ‏بِخَرَاجٍ ‏ ‏يَجْرِي لَهُ عَلَيْنَا وَلَكِنْ ‏ ‏نُلْقِي إِلَيْهِ الْحَرْبَ فَقَالَ قَدْ كَانَ ذَاكَ وَلَكِنِّي كَرِهْتُ أَنْ ‏ ‏أَفْتَاتَ ‏ ‏دُونَكُمْ بِأَمْرٍ ‏ ‏قَالَ ‏ ‏عَبَّادٌ ‏ ‏فَقُلْتُ ‏ ‏لِابْنِ خُثَيْمٍ ‏ ‏أَوَلَيْسَ قَدْ كَانَ قَارَبَ وَهَمَّ بِالْإِسْلَامِ فِيمَا بَلَغَنَا قَالَ بَلَى لَوْلَا أَنَّهُ رَأَى مِنْهُمْ ‏ ‏قَالَ فَقَالَ ‏ ‏ابْغُونِي ‏ ‏رَجُلًا مِنْ ‏ ‏الْعَرَبِ ‏ ‏أَكْتُبْ مَعَهُ إِلَيْهِ جَوَابَ كِتَابِهِ قَالَ فَأَتَيْتُ وَأَنَا شَابٌّ فَانْطُلِقَ بِي إِلَيْهِ فَكَتَبَ جَوَابَهُ وَقَالَ لِي مَهْمَا نَسِيتَ مِنْ شَيْءٍ فَاحْفَظْ عَنِّي ثَلَاثَ ‏ ‏خِلَالٍ ‏ ‏انْظُرْ إِذَا هُوَ قَرَأَ كِتَابِي هَلْ يَذْكُرُ اللَّيْلَ وَالنَّهَارَ وَهَلْ يَذْكُرُ كِتَابَهُ إِلَيَّ وَانْظُرْ هَلْ تَرَى ‏ ‏فِي ظَهْرِهِ ‏ ‏عَلَمًا ‏ ‏قَالَ فَأَقْبَلْتُ حَتَّى أَتَيْتُهُ وَهُوَ ‏ ‏بِتَبُوكَ ‏ ‏فِي ‏ ‏حَلْقَةٍ ‏ ‏مِنْ أَصْحَابِهِ ‏ ‏مُحْتَبِينَ ‏ ‏فَسَأَلْتُ فَأُخْبِرْتُ بِهِ فَدَفَعْتُ إِلَيْهِ الْكِتَابَ فَدَعَا ‏ ‏مُعَاوِيَةَ ‏ ‏فَقَرَأَ عَلَيْهِ الْكِتَابَ فَلَمَّا أَتَى عَلَى قَوْلِهِ دَعَوْتَنِي إِلَى جَنَّةٍ عَرْضُهَا السَّمَوَاتُ وَالْأَرْضُ فَأَيْنَ النَّارُ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا جَاءَ اللَّيْلُ فَأَيْنَ النَّهَارُ قَالَ فَقَالَ إِنِّي قَدْ كَتَبْتُ إِلَى ‏ ‏النَّجَاشِيِّ ‏ ‏فَخَرَّقَهُ ‏ ‏فَخَرَّقَهُ اللَّهُ ‏ ‏مُخَرَّقَ ‏ ‏الْمُلْكِ ‏ ‏قَالَ ‏ ‏عَبَّادٌ ‏ ‏فَقُلْتُ ‏ ‏لِابْنِ خُثَيْمٍ ‏ ‏أَلَيْسَ قَدْ أَسْلَمَ ‏ ‏النَّجَاشِيُّ ‏ ‏وَنَعَاهُ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْمَدِينَةِ ‏ ‏إِلَى أَصْحَابِهِ فَصَلَّى عَلَيْهِ قَالَ بَلَى ذَاكَ فُلَانُ بْنُ فُلَانٍ وَهَذَا فُلَانُ بْنُ فُلَانٍ قَدْ ذَكَرَهُمْ ‏ ‏ابْنُ خُثَيْمٍ ‏ ‏جَمِيعًا وَنَسِيتُهُمَا ‏ ‏وَكَتَبْتُ إِلَى ‏ ‏كِسْرَى ‏ ‏كِتَابًا فَمَزَّقَهُ فَمَزَّقَهُ اللَّهُ تَمْزِيقَ الْمُلْكِ وَكَتَبْتُ إِلَى ‏ ‏قَيْصَرَ ‏ ‏كِتَابًا فَأَجَابَنِي فِيهِ فَلَمْ تَزَلْ النَّاسُ يَخْشَوْنَ مِنْهُمْ ‏ ‏بَأْسًا ‏ ‏مَا كَانَ فِي الْعَيْشِ خَيْرٌ ثُمَّ قَالَ لِي مَنْ أَنْتَ قُلْتُ مِنْ ‏ ‏تَنُوخٍ ‏ ‏قَالَ يَا أَخَا ‏ ‏تَنُوخٍ ‏ ‏هَلْ لَكَ فِي الْإِسْلَامِ قُلْتُ لَا إِنِّي أَقْبَلْتُ مِنْ قِبَلِ قَوْمٍ وَأَنَا فِيهِمْ عَلَى دِينٍ وَلَسْتُ مُسْتَبْدِلًا بِدِينِهِمْ حَتَّى أَرْجِعَ إِلَيْهِمْ قَالَ فَضَحِكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ تَبَسَّمَ ‏ ‏فَلَمَّا قَضَيْتُ حَاجَتِي قُمْتُ فَلَمَّا ‏ ‏وَلَّيْتُ ‏ ‏دَعَانِي فَقَالَ يَا أَخَا ‏ ‏تَنُوخٍ ‏ ‏هَلُمَّ ‏ ‏فَامْضِ لِلَّذِي أُمِرْتَ بِهِ قَالَ وَكُنْتُ قَدْ نَسِيتُهَا فَاسْتَدَرْتُ مِنْ وَرَاءِ الْحَلْقَةِ وَيَلْقَى ‏ ‏بُرْدَةً ‏ ‏كَانَتْ عَلَيْهِ عَنْ ظَهْرِهِ فَرَأَيْتُ ‏ ‏غُضْرُوفَ ‏ ‏كَتِفِهِ مِثْلَ ‏ ‏الْمِحْجَمِ ‏ ‏الضَّخْمِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو عَامِرٍ حَوْثَرَةُ بْنُ أَشْرَسَ ‏ ‏إِمْلَاءً عَلَىَّ قَالَ أَخْبَرَنِي ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُثْمَانَ بْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي رَاشِدٍ ‏ ‏قَالَ كَانَ رَسُولُ ‏ ‏قَيْصَرَ ‏ ‏جَارًا لِي زَمَنَ ‏ ‏يَزِيدَ بْنِ مُعَاوِيَةَ ‏ ‏فَقُلْتُ لَهُ أَخْبِرْنِي عَنْ كِتَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏قَيْصَرَ ‏ ‏فَقَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْسَلَ ‏ ‏دِحْيَةَ الْكَلْبِيَّ ‏ ‏إِلَى ‏ ‏قَيْصَرَ ‏ ‏وَكَتَبَ مَعَهُ إِلَيْهِ كِتَابًا فَذَكَرَ نَحْوَ حَدِيثِ ‏ ‏عَبَّادِ بْنِ عَبَّادٍ ‏ ‏وَحَدِيثُ ‏ ‏عَبَّادٍ ‏ ‏أَتَمُّ وَأَحْسَنُ ‏ ‏اقْتِصَاصًا ‏ ‏لِلْحَدِيثِ ‏ ‏وَزَادَ قَالَ فَضَحِكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ دَعَاهُ إِلَى الْإِسْلَامِ فَأَبَى أَنْ يُسْلِمَ وَتَلَا هَذِهِ الْآيَةَ ‏ { ‏إِنَّكَ لَا تَهْدِي مَنْ أَحْبَبْتَ وَلَكِنَّ اللَّهَ يَهْدِي مَنْ يَشَاءُ ‏} ‏ثُمَّ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّكَ رَسُولُ قَوْمٍ وَإِنَّ لَكَ حَقًّا وَلَكِنْ جِئْتَنَا وَنَحْنُ ‏ ‏مُرْمِلُونَ ‏ ‏فَقَالَ ‏ ‏عُثْمَانُ بْنُ عَفَّانَ ‏ ‏أَنَا ‏ ‏أَكْسُوهُ ‏ ‏حُلَّةً ‏ ‏صَفُورِيَّةً وَقَالَ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏عَلَيَّ ضِيَافَتُهُ ‏","","",""],[16098,16098,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ الْبُرْسَانِيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ أَبِي زِيَادٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ كَثِيرٍ الدَّارِيُّ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَيْخٌ أَدْرَكَ الْجَاهِلِيَّةَ وَنَحْنُ فِي غَزْوَةِ ‏ ‏رُودِسَ ‏ ‏يُقَالُ لَهُ ‏ ‏ابْنُ عَبْسٍ ‏ ‏قَالَ ‏ ‏كُنْتُ أَسُوقُ لِآلٍ لَنَا بَقَرَةً قَالَ فَسَمِعْتُ مِنْ جَوْفِهَا يَا آلَ ‏ ‏ذَرِيحٍ ‏ ‏قَوْلٌ فَصِيحٌ ‏ ‏رَجُلٌ يَصِيحُ لَا إِلَهَ إِلَّا اللَّهُ قَالَ فَقَدِمْنَا ‏ ‏مَكَّةَ ‏ ‏فَوَجَدْنَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ خَرَجَ ‏ ‏بِمَكَّةَ ‏","","",""],[16099,16099,"","","‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو مُوسَى الْعَنْزِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ بْنُ عَبْدِ الْوَارِثِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَكَنُ بْنُ الْمُغِيرَةِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الْوَلِيدُ بْنُ أَبِي هِشَامٍ ‏ ‏عَنْ ‏ ‏فَرْقَدٍ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ خَبَّابٍ السُّلَمِيِّ ‏ ‏قَالَ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَحَثَّ عَلَى جَيْشِ الْعُسْرَةِ فَقَالَ ‏ ‏عُثْمَانُ بْنُ عَفَّانَ ‏ ‏عَلَيَّ مِائَةُ بَعِيرٍ ‏ ‏بِأَحْلَاسِهَا ‏ ‏وَأَقْتَابِهَا ‏ ‏قَالَ ثُمَّ حَثَّ فَقَالَ ‏ ‏عُثْمَانُ ‏ ‏عَلَيَّ مِائَةٌ أُخْرَى ‏ ‏بِأَحْلَاسِهَا ‏ ‏وَأَقْتَابِهَا ‏ ‏قَالَ ثُمَّ نَزَلَ مَرْقَاةً مِنْ الْمِنْبَرِ ثُمَّ حَثَّ فَقَالَ ‏ ‏عُثْمَانُ بْنُ عَفَّانَ ‏ ‏عَلَيَّ مِائَةٌ أُخْرَى ‏ ‏بِأَحْلَاسِهَا ‏ ‏وَأَقْتَابِهَا ‏ ‏قَالَ فَرَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ بِيَدِهِ هَكَذَا يُحَرِّكُهَا ‏ ‏وَأَخْرَجَ ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏يَدَهُ كَالْمُتَعَجِّبِ مَا عَلَى ‏ ‏عُثْمَانَ ‏ ‏مَا عَمِلَ بَعْدَ هَذَا ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو مُوسَى الْعَنَزِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَكَنُ بْنُ الْمُغِيرَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ خَبَّابٍ السُّلَمِيِّ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَطَبَ فَحَضَّ عَلَى جَيْشِ الْعُسْرَةِ ‏ ‏فَذَكَرَهُ ‏","","",""],[16100,16100,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو مُوسَى الْعَنَزِيُّ مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنِ ‏ ‏ابْنِ عَوْنٍ ‏ ‏عَنْ ‏ ‏كُلْثُومِ بْنِ جَبْرٍ ‏ ‏قَالَ ‏ ‏كُنَّا ‏ ‏بِوَاسِطِ الْقَصَبِ ‏ ‏عِنْدَ ‏ ‏عَبْدِ الْأَعْلَى بْنِ عَبْدِ اللَّهِ بْنِ عَامِرٍ ‏ ‏قَالَ فَإِذَا عِنْدَهُ رَجُلٌ يُقَالُ لَهُ ‏ ‏أَبُو الْغَادِيَةِ ‏ ‏اسْتَسْقَى مَاءً فَأُتِيَ بِإِنَاءٍ مُفَضَّضٍ فَأَبَى أَنْ يَشْرَبَ وَذَكَرَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ هَذَا الْحَدِيثَ ‏ ‏لَا تَرْجِعُوا بَعْدِي كُفَّارًا ‏ ‏أَوْ ضُلَّالًا شَكَّ ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏يَضْرِبُ بَعْضُكُمْ رِقَابَ بَعْضٍ فَإِذَا رَجُلٌ يَسُبُّ فُلَانًا فَقُلْتُ وَاللَّهِ لَئِنْ أَمْكَنَنِي اللَّهُ مِنْكَ فِي ‏ ‏كَتِيبَةٍ ‏ ‏فَلَمَّا كَانَ يَوْمُ ‏ ‏صِفِّينَ ‏ ‏إِذَا أَنَا بِهِ وَعَلَيْهِ ‏ ‏دِرْعٌ ‏ ‏قَالَ فَفَطِنْتُ إِلَى الْفُرْجَةِ فِي جُرُبَّانِ ‏ ‏الدِّرْعِ ‏ ‏فَطَعَنْتُهُ فَقَتَلْتُهُ فَإِذَا هُوَ ‏ ‏عَمَّارُ بْنُ يَاسِرٍ ‏ ‏قَالَ قُلْتُ وَأَيَّ يَدٍ ‏ ‏كَفَتَاهُ ‏ ‏يَكْرَهُ أَنْ يَشْرَبَ فِي إِنَاءٍ ‏ ‏مُفَضَّضٍ ‏ ‏وَقَدْ قَتَلَ ‏ ‏عَمَّارَ بْنَ يَاسِرٍ ‏","","",""],[16101,16101,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ بْنُ عَبْدِ الْوَارِثِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏رَبِيعَةُ بْنُ كُلْثُومٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِي غَادِيَةَ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏خَطَبَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏الْعَقَبَةِ ‏ ‏فَقَالَ يَا أَيُّهَا النَّاسُ ‏ ‏إِنَّ دِمَاءَكُمْ وَأَمْوَالَكُمْ عَلَيْكُمْ حَرَامٌ إِلَى أَنْ تَلْقَوْا رَبَّكُمْ كَحُرْمَةِ يَوْمِكُمْ هَذَا فِي بَلَدِكُمْ هَذَا فِي شَهْرِكُمْ هَذَا أَلَا هَلْ بَلَّغْتُ قَالُوا نَعَمْ قَالَ اللَّهُمَّ هَلْ بَلَّغْتُ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏رَبِيعَةُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا غَادِيَةَ الْجُهَنِيَّ ‏ ‏قَالَ ‏ ‏بَايَعْتُ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏الْعَقَبَةِ ‏ ‏فَقَالَ يَا أَيُّهَا النَّاسُ إِنَّ دِمَاءَكُمْ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[16102,16102,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنِي ‏ ‏الصَّلْتُ بْنُ مَسْعُودٍ الْجَحْدَرِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ الطُّفَاوِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْعَاصِ بْنَ عَمْرٍو الطُّفَاوِيَّ ‏ ‏قَالَ ‏ ‏خَرَجَ ‏ ‏أَبُو الْغَادِيَةِ ‏ ‏وحَبِيبُ بْنُ الْحَارِثِ ‏ ‏وَأُمُّ أَبِي الْعَالِيَةِ ‏ ‏مُهَاجِرِينَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَسْلَمُوا فَقَالَتْ الْمَرْأَةُ أَوْصِنِي يَا رَسُولَ اللَّهِ قَالَ ‏ ‏إِيَّاكِ وَمَا يَسُوءُ الْأُذُنَ ‏","","",""],[16103,16103,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكَّارٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏يَعْقُوبَ بْنِ بَحِيرٍ ‏ ‏عَنْ ‏ ‏ضِرَارِ بْنِ الْأَزْوَرِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ بِهِ وَهُوَ يَحْلِبُ فَقَالَ دَعْ دَاعِيَ اللَّبَنِ ‏","","",""],[16104,16104,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ مُحَمَّدِ بْنِ عَبْدِ اللَّهِ ‏ ‏جَارُنَا ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَعِيدٍ الْبَاهِلِيُّ الْأَثْرَمُ الْبَصْرِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَلَّامُ بْنُ سُلَيْمَانَ الْقَارِئُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَاصِمُ بْنُ بَهْدَلَةَ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏ضِرَارِ بْنِ الْأَزْوَرِ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ امْدُدْ يَدَكَ أُبَايِعْكَ عَلَى الْإِسْلَامِ قَالَ ‏ ‏ضِرَارٌ ‏ ‏ثُمَّ قُلْتُ ‏ ‏تَرَكْتُ ‏ ‏الْقِدَاحَ ‏ ‏وَعَزْفَ ‏ ‏الْقِيَانِ ‏ ‏وَالْخَمْرَ تَصْلِيَةً وَابْتِهَالَا ‏ ‏وَكَرِّي ‏ ‏الْمُحَبَّرَ ‏ ‏فِي غَمْرَةٍ ‏ ‏وَحَمْلِي عَلَى الْمُشْرِكِينَ ‏ ‏الْقِتَالَا ‏ ‏فَيَا رَبِّ لَا ‏ ‏أُغْبَنَنْ ‏ ‏صَفْقَتِي ‏ ‏فَقَدْ بِعْتُ مَالِي وَأَهْلِي ‏ ‏ابْتِدَالَا ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا ‏ ‏غُبِنَتْ ‏ ‏صَفْقَتُكَ يَا ‏ ‏ضِرَارُ ‏","","",""],[16105,16105,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ نُمَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏يَعْقُوبَ بْنِ بَحِيرٍ ‏ ‏عَنْ ‏ ‏ضِرَارِ بْنِ الْأَزْوَرِ ‏ ‏قَالَ ‏ ‏بَعَثَنِي أَهْلِي ‏ ‏بِلَقُوحٍ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَمَرَنِي أَنْ أَحْلِبَهَا فَحَلَبْتُهَا فَقَالَ دَعْ دَاعِيَ اللَّبَنِ ‏","","",""],[16106,16106,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو صَالِحٌ الْحَكَمُ بْنُ مُوسَى ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عِيسَى بْنُ يُونُسَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَوْ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِعَرَفَةَ ‏ ‏فَأَخَذْتُ ‏ ‏بِزِمَامِ ‏ ‏نَاقَتِهِ ‏ ‏أَوْ ‏ ‏بِخِطَامِهَا ‏ ‏فَدَفَعْتُ عَنْهُ فَقَالَ دَعُوهُ ‏ ‏فَأَرَبٌ ‏ ‏مَا جَاءَ بِهِ فَقُلْتُ ‏ ‏نَبِّئْنِي بِعَمَلٍ يُقَرِّبُنِي إِلَى الْجَنَّةِ وَيُبْعِدُنِي مِنْ النَّارِ قَالَ فَرَفَعَ رَأْسَهُ إِلَى السَّمَاءِ ثُمَّ قَالَ لَئِنْ كُنْتَ أَوْجَزْتَ فِي الْخُطْبَةِ لَقَدْ أَعْظَمْتَ ‏ ‏أَوْ أَطْوَلْتَ ‏ ‏تَعْبُدُ اللَّهَ لَا تُشْرِكُ بِهِ شَيْئًا وَتُقِيمُ الصَّلَاةَ ‏ ‏وَتُؤْتِي الزَّكَاةَ وَتَحُجُّ ‏ ‏الْبَيْتَ ‏ ‏وَتَصُومُ رَمَضَانَ ‏ ‏وَتَأْتِي إِلَى النَّاسِ مَا تُحِبُّ أَنْ يُؤْتُوهُ إِلَيْكَ وَمَا كَرِهْتَ لِنَفْسِكَ فَدَعْ النَّاسَ مِنْهُ خَلِّ عَنْ ‏ ‏زِمَامِ ‏ ‏النَّاقَةِ ‏","","",""],[16107,16107,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو مُوسَى الْعَنَزِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَثْمَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ بَشِيرٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي الشَّعْثَاءِ ‏ ‏عَنْ ‏ ‏يُونُسَ بْنِ شَدَّادٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ صَوْمِ ‏ ‏أَيَّامِ التَّشْرِيقِ ‏","","",""],[16108,16108,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْدِيُّ بْنُ سُلَيْمَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعَيْثُ بْنُ مُطَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏مُطَيْرٍ ‏ ‏ومُطَيْرٌ ‏ ‏حَاضِرٌ يُصَدِّقُهُ مَقَالَتَهُ ‏ ‏قَالَ ‏ ‏كَيْفَ كُنْتُ أَخْبَرْتُكَ قَالَ يَا أَبَتَاهُ أَخْبَرْتَنِي أَنَّكَ لَقِيَكَ ‏ ‏ذُو الْيَدَيْنِ ‏ ‏بِذِي خُشُبٍ ‏ ‏فَأَخْبَرَكَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى بِهِمْ إِحْدَى صَلَاتَيْ الْعَشِيِّ وَهِيَ الْعَصْرُ فَصَلَّى رَكْعَتَيْنِ وَخَرَجَ ‏ ‏سَرَعَانُ ‏ ‏النَّاسِ وَهُمْ يَقُولُونَ أَقَصُرَتْ الصَّلَاةُ فَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاتَّبَعَهُ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏وَهُمَا مُبْتَدٍ فَلَحِقَهُ ‏ ‏ذُو الْيَدَيْنِ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ أَقَصُرَتْ الصَّلَاةُ أَقَصُرَتْ الصَّلَاةُ أَمْ نَسِيتَ فَقَالَ ‏ ‏مَا قَصُرَتْ وَلَا نَسِيتُ ثُمَّ أَقْبَلَ عَلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏فَقَالَ مَا يَقُولُ ‏ ‏ذُو الْيَدَيْنِ ‏ ‏فَقَالَا صَدَقَ يَا رَسُولَ اللَّهِ فَرَجَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَثَابَ ‏ ‏النَّاسُ فَصَلَّى رَكْعَتَيْنِ ثُمَّ سَلَّمَ ثُمَّ سَجَدَ سَجْدَتَيْ السَّهْوِ ‏ ‏قَالَ ‏ ‏أَبُو سُلَيْمَانَ ‏ ‏حَدَّثْتُ سِتَّ سِنِينَ ‏ ‏أَوْ سَبْعَ سِنِينَ ‏ ‏ثُمَّ سَلَّمَ وَشَكَكْتُ فِيهِ وَهُوَ أَكْثَرُ حِفْظِي ‏","","",""],[16109,16109,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏نَصْرُ بْنُ عَلِيٍّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مَعْدِيُّ بْنُ سُلَيْمَانَ ‏ ‏قَالَ ‏ ‏أَتَيْتُ ‏ ‏مُطَيْرًا ‏ ‏لِأَسْأَلَهُ عَنْ حَدِيثِ ‏ ‏ذِي الْيَدَيْنِ ‏ ‏فَأَتَيْتُهُ فَسَأَلْتُهُ فَإِذَا هُوَ شَيْخٌ كَبِيرٌ لَا يُنْفِذُ الْحَدِيثَ مِنْ الْكِبَرِ ‏ ‏فَقَالَ ‏ ‏ابْنُهُ ‏ ‏شُعَيْثٌ ‏ ‏بَلَى يَا ‏ ‏أَبَتِ ‏ ‏حَدَّثَتْنِي أَنَّ ‏ ‏ذَا الْيَدَيْنِ ‏ ‏لَقِيَكَ ‏ ‏بِذِي خَشَبٍ ‏ ‏فَحَدَّثَكَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى بِهِمْ إِحْدَى صَلَاتَيْ الْعَشِيِّ وَهِيَ الْعَصْرُ رَكْعَتَيْنِ ثُمَّ سَلَّمَ فَخَرَجَ ‏ ‏سَرَعَانُ ‏ ‏النَّاسِ فَقَالَ أَقَصُرَتْ الصَّلَاةُ وَفِي الْقَوْمِ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏فَقَالَ ‏ ‏ذُو الْيَدَيْنِ ‏ ‏أَقَصُرَتْ الصَّلَاةُ أَمْ نَسِيتَ قَالَ ‏ ‏مَا قَصُرَتْ الصَّلَاةُ وَلَا نَسِيتُ ثُمَّ أَقْبَلَ عَلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏فَقَالَ مَا يَقُولُ ‏ ‏ذُو الْيَدَيْنِ ‏ ‏فَقَالَا صَدَقَ يَا رَسُولَ اللَّهِ فَرَجَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَثَابَ ‏ ‏النَّاسُ وَصَلَّى بِهِمْ رَكْعَتَيْنِ ثُمَّ سَلَّمَ ثُمَّ سَجَدَ بِهِمْ سَجْدَتَيْ السَّهْوِ ‏","","",""],[16110,16110,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو مَعْمَرٍ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي حَازِمٍ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى ‏ ‏عَلِيِّ بْنِ حُسَيْنٍ ‏ ‏فَقَالَ ‏ ‏مَا كَانَ مَنْزِلَةُ ‏ ‏أَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏مِنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مَنْزِلَتُهُمَا السَّاعَةَ ‏","","",""],[16111,16111,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ الْقَوَارِيرِيُّ ‏ ‏وَخَلَفُ بْنُ هِشَامٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَامِرُ بْنُ أَبِي عَامِرٍ الْخَزَّازُ ‏ ‏عَنْ ‏ ‏أَيُّوبَ بْنِ مُوسَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا ‏ ‏نَحَلَ ‏ ‏وَالِدٌ وَلَدَهُ ‏ ‏نُحْلًا ‏ ‏أَفْضَلَ مِنْ أَدَبٍ حَسَنٍ ‏","","",""],[16112,16112,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ الدَّرَاوَرْدِيُّ ‏ ‏قَالَ ‏ ‏عَمْرُو بْنُ يَحْيَى ‏ ‏حَدَّثَنِي عَنْ ‏ ‏يَحْيَى بْنِ عُمَارَةَ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَبِي حَسَنٍ ‏ ‏قَالَ ‏ ‏دَخَلْتُ الْأَسْوَاقَ وَقَالَ فَأَثَرْتُ ‏ ‏وَقَالَ ‏ ‏الْقَوَارِيرِيُّ ‏ ‏مَرَّةً فَأَخَذْتُ ‏ ‏دُبْسَتَيْنِ ‏ ‏قَالَ وَأُمُّهُمَا تُرَشْرِشُ عَلَيْهِمَا وَأَنَا أُرِيدُ أَنْ آخُذَهُمَا قَالَ فَدَخَلَ عَلَيَّ ‏ ‏أَبُو حَسَنٍ ‏ ‏فَنَزَعَ ‏ ‏مِتِّيخَةً ‏ ‏قَالَ فَضَرَبَنِي بِهَا فَقَالَتْ لِي امْرَأَةٌ مِنَّا يُقَالُ لَهَا ‏ ‏مَرْيَمُ ‏ ‏لَقَدْ تَعِسْتَ مِنْ عَضُدِهِ وَمِنْ تَكْسِيرِ ‏ ‏الْمِتِّيخَةِ ‏ ‏فَقَالَ لِي أَلَمْ تَعْلَمْ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَرَّمَ مَا بَيْنَ ‏ ‏لَابَتَيْ ‏ ‏الْمَدِينَةِ ‏","","",""],[16113,16113,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْفَضْلِ الْمَرْوَزِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ أَبِي أُوَيْسٍ ‏ ‏قَالَ وَحَدَّثَنِي ‏ ‏حُسَيْنُ بْنُ عَبْدِ اللَّهِ ابْنِ ضُمَيْرَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ يَحْيَى الْمَازِنِيِّ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَبِي حَسَنٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَكْرَهُ نِكَاحَ السِّرِّ حَتَّى يُضْرَبَ بِدُفٍّ وَيُقَالَ ‏ ‏أَتَيْنَاكُمْ أَتَيْنَاكُمْ ‏ ‏فَحَيُّونَا ‏ ‏نُحَيِّيكُمْ ‏","","",""],[16114,16114,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ حَاتِمٍ الطَّوِيلُ ‏ ‏وَكَانَ ثِقَةً رَجُلًا صَالِحًا ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ يَعْنِي الدَّرَاوَرْدِيَّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَوْ ‏ ‏عَمِّهِ ‏ ‏قَالَ ‏ ‏كَانَتْ لِي ‏ ‏جُمَّةٌ ‏ ‏كُنْتُ إِذَا سَجَدْتُ رَفَعْتُهَا فَرَآنِي ‏ ‏أَبُو حَسَنٍ الْمَازِنِيُّ ‏ ‏فَقَالَ تَرْفَعُهَا لَا يُصِيبُهَا التُّرَابُ وَاللَّهِ لَأَحْلِقَنَّهَا فَحَلَقَهَا ‏","","",""],[16115,16115,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو مَالِكٍ الْحَنَفِيُّ كَثِيرُ بْنُ يَحْيَى بْنِ كَثِيرٍ الْبَصْرِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ثَابِتٌ أَبُو زَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِلَالُ بْنُ خَبَّابٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ بْنِ خَالِدٍ الْمَخْزُومِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَرِيفٌ ‏ ‏مِنْ عُرَفَاءِ ‏ ‏قُرَيْشٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏سَمِعَهُ مِنْ فَلْقِ ‏ ‏فِي رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ صَامَ رَمَضَانَ وَشَوَّالَ وَالْأَرْبِعَاءَ وَالْخَمِيسَ دَخَلَ الْجَنَّةَ ‏","","",""],[16116,16116,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنِي ‏ ‏سُرَيْجُ بْنُ يُونُسَ ‏ ‏مِنْ كِتَابِهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبُو إِسْمَاعِيلَ الْمُؤَدِّبُ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ عَائِذٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْطُبُ عَلَى نَاقَةٍ ‏ ‏خَرْمَاءَ ‏ ‏وَعَبْدٌ حَبَشِيٌّ مُمْسِكٌ ‏ ‏بِخِطَامِهَا ‏ ‏وَهَلَكَ ‏ ‏قَيْسٌ ‏ ‏أَيَّامَ ‏ ‏الْمُخْتَارِ ‏","","",""],[16117,16117,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ أَبِي بَكْرٍ الْمُقَدَّمِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو مَعْشَرٍ الْبَرَاءُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ حَرْمَلَةَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ هِنْدِ بْنِ حَارِثَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏وَكَانَ مِنْ أَصْحَابِ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏وَأَخُوهُ الَّذِي بَعَثَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْمُرُ قَوْمَهُ بِصِيَامِ يَوْمِ عَاشُورَاءَ وَهُوَ ‏ ‏أَسْمَاءُ بْنُ حَارِثَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَهُ فَقَالَ ‏ ‏مُرْ قَوْمَكَ فَلْيَصُومُوا هَذَا الْيَوْمَ قَالَ أَرَأَيْتَ إِنْ وَجَدْتُهُمْ قَدْ طَعِمُوا قَالَ فَلْيُتِمُّوا بَقِيَّةَ يَوْمِهِمْ ‏","","",""],[16118,16118,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏نَضْرُ بْنُ عَلِيٍّ الْجَهْضَمِيُّ ‏ ‏وَعَبْدُ الْأَعْلَى بْنُ حَمَّادٍ أَبُو يَحْيَى النَّرْسِيُّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَامِرُ بْنُ أَبِي عَامِرٍ الْخَزَّازُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَيُّوبُ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا ‏ ‏نَحَلَ ‏ ‏وَالِدٌ وَلَدًا أَفْضَلَ مِنْ أَدَبٍ حَسَنٍ ‏","","",""],[16119,16119,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ ثَعْلَبَةَ بْنِ سَوَاءٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَوَاءٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حُمْرَانُ بْنُ يَزِيدَ الْأَعْمَى ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏بَنِي سَدُوسٍ ‏ ‏عَنْ ‏ ‏قُطْبَةَ بْنِ قَتَادَةَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُفْطِرُ إِذَا غَرَبَتْ الشَّمْسُ ‏","","",""],[16120,16120,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ ثَعْلَبَةَ بْنِ سَوَاءٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ سَوَاءٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏حُمْرَانُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏بَنِي سَدُوسٍ ‏ ‏عَنْ ‏ ‏قُطْبَةَ بْنِ قَتَادَةَ ‏ ‏قَالَ ‏ ‏بَايَعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ابْنَتِي ‏ ‏الْحَوْصَلَةِ ‏ ‏وَكَانَ ‏ ‏يُكَنَّى ‏ ‏بِأَبِي الْحَوْصَلَةِ ‏","","",""],[16121,16121,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنِي ‏ ‏نَصْرُ بْنُ عَلِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يُوسُفُ بْنُ خَالِدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو جَعْفَرٍ الْخَطْمِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عُقْبَةَ بْنِ الْفَاكِهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏الْفَاكِهِ بْنِ سَعْدٍ ‏ ‏وَكَانَتْ لَهُ صُحْبَةٌ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَغْتَسِلُ يَوْمَ الْجُمُعَةِ وَيَوْمَ ‏ ‏عَرَفَةَ ‏ ‏وَيَوْمَ الْفِطْرِ ‏ ‏وَيَوْمَ النَّحْرِ ‏ ‏قَالَ ‏ ‏وَكَانَ ‏ ‏الْفَاكِهُ بْنُ سَعْدٍ ‏ ‏يَأْمُرُ أَهْلَهُ بِالْغُسْلِ فِي هَذِهِ الْأَيَّامِ ‏","","",""],[16122,16122,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنِي ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ أَبُو مَعْمَرٍ الْهُذَلِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ خُثَيْمٍ الْهِلَالِيُّ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏جَدَّتِي أُمُّ أَبِي ‏ ‏رَبِيعَةُ بِنْتُ عِيَاضٍ الْكِلَابِيَّةُ ‏ ‏عَنْ ‏ ‏جَدِّهَا ‏ ‏عَبِيدَةَ بْنِ عَمْرٍو الْكِلَابِيِّ ‏ ‏قَالَ ‏ ‏رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏يَتَوَضَّأُ ‏ ‏فَأَسْبَغَ ‏ ‏الطُّهُورَ ‏ ‏وَكَانَتْ هِيَ ‏ ‏إِذَا تَوَضَّأَتْ ‏ ‏أَسْبَغَتْ ‏ ‏الطُّهُورَ حَتَّى تَرْفَعَ ‏ ‏الْخِمَارَ ‏ ‏فَتَمْسَحَ رَأْسَهَا ‏","","",""],[16123,16123,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنِي ‏ ‏عُثْمَانُ بْنُ مُحَمَّدِ بْنِ أَبِي شَيْبَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ خُثَيْمٍ الْهِلَالِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَدَّتِي ‏ ‏رَبِيعَةَ ابْنَةَ عِيَاضٍ ‏ ‏عَنْ ‏ ‏جَدِّهَا ‏ ‏عَبِيدَةَ بْنِ عَمْرٍو الْكِلَابِيِّ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ ‏ ‏فَأَسْبَغَ ‏ ‏الْوُضُوءَ ‏ ‏قَالَ ‏ ‏وَكَانَتْ ‏ ‏رَبِيعَةُ ‏ ‏إِذَا تَوَضَّأَتْ ‏ ‏أَسْبَغَتْ ‏ ‏الْوُضُوءَ ‏","","",""],[16124,16124,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏عَمْرُو بْنُ مُحَمَّدٍ النَّاقِدُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ خُثَيْمٍ الْهِلَالِيُّ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏جَدَّتِي ‏ ‏رَبِيعَةُ ابْنَةُ عِيَاضٍ الْكِلَابِيَّةُ ‏ ‏عَنْ ‏ ‏جَدِّهَا ‏ ‏عَبِيدَةَ بْنِ عَمْرٍو الْكِلَابِيِّ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ ‏ ‏فَأَسْبَغَ ‏ ‏الطُّهُورَ ‏ ‏قَالَ ‏ ‏وَكَانَتْ هِيَ ‏ ‏يَعْنِي جَدَّتَهُ ‏ ‏إِذَا أَخَذَتْ الطَّهُورَ ‏ ‏أَسْبَغَتْ ‏","","",""],[16125,16125,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏مَرْثَدِ بْنِ عَبْدِ اللَّهِ الْيَزَنِيِّ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ هُبَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ مُؤْمِنٍ يَمُوتُ فَيُصَلِّي عَلَيْهِ أُمَّةٌ مِنْ الْمُسْلِمِينَ بَلَغُوا أَنْ يَكُونُوا ‏ ‏ثَلَاثَةَ ‏ ‏صُفُوفٍ إِلَّا غُفِرَ لَهُ ‏ ‏قَالَ ‏ ‏فَكَانَ ‏ ‏مَالِكُ بْنُ هُبَيْرَةَ ‏ ‏يَتَحَرَّى ‏ ‏إِذَا قَلَّ أَهْلُ جَنَازَةٍ أَنْ يَجْعَلَهُمْ ثَلَاثَةَ صُفُوفٍ ‏","","",""],[16126,16126,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏الْمِقْدَادِ بْنِ الْأَسْوَدِ ‏ ‏قَالَ ‏ ‏قَالَ لِي ‏ ‏عَلِيٌّ ‏ ‏سَلْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الرَّجُلِ يُلَاعِبُ امْرَأَتَهُ فَيَخْرُجُ مِنْهُ ‏ ‏الْمَذْيُ ‏ ‏مِنْ غَيْرِ ‏ ‏مَاءِ ‏ ‏الْحَيَاةِ قَالَ يَغْسِلُ فَرْجَهُ وَيَتَوَضَّأُ وُضُوءَهُ لِلصَّلَاةِ ‏","","",""],[16127,16127,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏إِسْرَائِيلُ بْنُ يُونُسَ بْنِ أَبِي إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ عَبْدِ الْأَعْلَى ‏ ‏عَنْ ‏ ‏جَدَّتِهِ ‏ ‏عَنْ ‏ ‏أَبِيهَا ‏ ‏سُوَيْدِ بْنِ حَنْظَلَةَ ‏ ‏قَالَ ‏ ‏خَرَجْنَا نُرِيدُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَعَنَا ‏ ‏وَائِلُ بْنُ حُجْرٍ ‏ ‏فَأَخَذَهُ عَدُوٌّ لَهُ ‏ ‏فَتَحَرَّجَ ‏ ‏النَّاسُ أَنْ يَحْلِفُوا وَحَلَفْتُ أَنَّهُ أَخِي فَخَلَّى عَنْهُ فَأَتَيْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرْتُ ذَلِكَ لَهُ فَقَالَ أَنْتَ كُنْتَ أَبَرَّهُمْ وَأَصْدَقَهُمْ صَدَقْتَ ‏ ‏الْمُسْلِمُ أَخُو الْمُسْلِمِ ‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ الْقَاسِمِ ‏ ‏وأَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ عَبْدِ الْأَعْلَى ‏ ‏عَنْ ‏ ‏جَدَّتِهِ ‏ ‏عَنْ ‏ ‏أَبِيهَا ‏ ‏سُوَيْدِ بْنِ حَنْظَلَةَ ‏ ‏قَالَ ‏ ‏خَرَجْنَا نُرِيدُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَهُ ‏","","",""],[16128,16128,"","","‏ ‏حَدَّثَنَا ‏ ‏صَفْوَانُ بْنُ عِيسَى ‏ ‏قَالَ أَنَا ‏ ‏الْحَارِثُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مُنِيرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ أَبِي ذُبَابٍ ‏ ‏قَالَ ‏ ‏قَدِمْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَسْلَمْتُ قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏اجْعَلْ لِقَوْمِي مَا أَسْلَمُوا عَلَيْهِ مِنْ أَمْوَالِهِمْ فَفَعَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاسْتَعْمَلَنِي عَلَيْهِمْ ثُمَّ اسْتَعْمَلَنِي ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏ثُمَّ اسْتَعْمَلَنِي ‏ ‏عُمَرُ ‏ ‏مِنْ بَعْدِهِ ‏","","",""],[16129,16129,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَنَا ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏طَاوُسًا ‏ ‏يُخْبِرُ عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏أَنَّهُ نَشَدَ قَضَاءَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ذَلِكَ فَجَاءَ ‏ ‏حَمَلُ بْنُ مَالِكِ بْنِ النَّابِغَةِ ‏ ‏فَقَالَ كُنْتُ بَيْنَ بَيْتَيْ ‏ ‏امْرَأَتَيَّ ‏ ‏فَضَرَبَتْ ‏ ‏إِحْدَاهُمَا ‏ ‏الْأُخْرَى ‏ ‏بِمِسْطَحٍ فَقَتَلَتْهَا وَجَنِينَهَا ‏ ‏فَقَضَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي جَنِينِهَا ‏ ‏بِغُرَّةٍ ‏ ‏وَأَنْ تُقْتَلَ بِهَا ‏ ‏قُلْتُ ‏ ‏لِعَمْرٍو ‏ ‏لَا أَخْبَرَنِي عَنْ أَبِيهِ بِكَذَا وَكَذَا قَالَ لَقَدْ شَكَّكْتَنِي ‏","","",""],[16130,16130,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو خَالِدٍ هُدْبَةُ بْنُ خَالِدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَمَّامُ بْنُ يَحْيَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو جَمْرَةَ الضُّبَعِيُّ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ صَلَّى ‏ ‏الْبَرْدَيْنِ ‏ ‏دَخَلَ الْجَنَّةَ ‏","","",""],[16131,16131,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏مِنْ كِتَابِهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏حُصَيْنٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ طَلْحَةَ بْنِ رُكَانَةَ ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةٌ فِي ‏ ‏مَسْجِدِي ‏ ‏هَذَا أَفْضَلُ مِنْ أَلْفِ صَلَاةٍ فِيمَا سِوَاهُ إِلَّا ‏ ‏الْمَسْجِدَ الْحَرَامَ ‏","","",""],[16132,16132,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَدْخُلُ الْجَنَّةَ قَاطِعٌ ‏","","",""],[16133,16133,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَوْ كَانَ ‏ ‏الْمُطْعِمُ بْنُ عَدِيٍّ ‏ ‏حَيًّا فَكَلَّمَنِي فِي هَؤُلَاءِ ‏ ‏النَّتْنَى ‏ ‏أَطْلَقْتُهُمْ ‏ ‏يَعْنِي أُسَارَى ‏ ‏بَدْرٍ ‏","","",""],[16134,16134,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ لِي أَسْمَاءً أَنَا ‏ ‏مُحَمَّدٌ ‏ ‏وَأَنَا ‏ ‏أَحْمَدُ ‏ ‏وَأَنَا ‏ ‏الْحَاشِرُ ‏ ‏الَّذِي يُحْشَرُ النَّاسُ عَلَى قَدَمِي وَأَنَا ‏ ‏الْمَاحِي ‏ ‏الَّذِي ‏ ‏يُمْحَى ‏ ‏بِيَ الْكُفْرُ وَأَنَا ‏ ‏الْعَاقِبُ ‏ ‏وَالْعَاقِبُ الَّذِي لَيْسَ بَعْدَهُ نَبِيٌّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[16135,16135,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ فِي الْمَغْرِبِ ‏ ‏بِالطُّورِ ‏","","",""],[16136,16136,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ بَابَاهُ ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏يَبْلُغُ بِهِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَا ‏ ‏بَنِي عَبْدِ مَنَافٍ ‏ ‏لَا تَمْنَعُنَّ أَحَدًا طَافَ بِهَذَا ‏ ‏الْبَيْتِ ‏ ‏أَوْ صَلَّى أَيَّ سَاعَةٍ مِنْ لَيْلٍ أَوْ نَهَارٍ ‏","","",""],[16137,16137,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏أَضْلَلْتُ بَعِيرًا لِي ‏ ‏بِعَرَفَةَ ‏ ‏فَذَهَبْتُ أَطْلُبُهُ فَإِذَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاقِفٌ قُلْتُ إِنَّ هَذَا مِنْ ‏ ‏الْحُمْسِ ‏ ‏مَا شَأْنُهُ هَاهُنَا ‏ ‏وَقَالَ ‏ ‏سُفْيَانُ ‏ ‏مَرَّةً ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ذَهَبْتُ أَطْلُبُ بَعِيرًا لِي ‏ ‏بِعَرَفَةَ ‏ ‏فَوَجَدْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاقِفًا قُلْتُ هَذَا مِنْ ‏ ‏الْحُمْسِ ‏ ‏مَا شَأْنُهُ هَاهُنَا ‏","","",""],[16138,16138,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى بْنُ عُبَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْخَيْفِ ‏ ‏مِنْ ‏ ‏مِنًى ‏ ‏فَقَالَ ‏ ‏نَضَّرَ ‏ ‏اللَّهُ امْرَأً سَمِعَ مَقَالَتِي فَوَعَاهَا ثُمَّ أَدَّاهَا إِلَى مَنْ لَمْ يَسْمَعْهَا فَرُبَّ حَامِلِ فِقْهٍ لَا فِقْهَ لَهُ وَرُبَّ حَامِلِ فِقْهٍ إِلَى مَنْ هُوَ أَفْقَهُ مِنْهُ ‏ ‏ثَلَاثٌ لَا ‏ ‏يَغِلُّ ‏ ‏عَلَيْهِمْ قَلْبُ الْمُؤْمِنِ إِخْلَاصُ الْعَمَلِ وَالنَّصِيحَةُ لِوَلِيِّ الْأَمْرِ وَلُزُومُ الْجَمَاعَةِ فَإِنَّ دَعْوَتَهُمْ تَكُونُ مِنْ وَرَائِهِ ‏","","",""],[16139,16139,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مِسْعَرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَمْرُو بْنُ مُرَّةَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏فِي التَّطَوُّعِ اللَّهُ أَكْبَرُ كَبِيرًا ثَلَاثَ مِرَارٍ وَالْحَمْدُ لِلَّهِ كَثِيرًا ثَلَاثَ مِرَارٍ وَسُبْحَانَ اللَّهِ بُكْرَةً وَأَصِيلًا ثَلَاثَ مِرَارٍ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ الشَّيْطَانِ الرَّجِيمِ مِنْ ‏ ‏هَمْزِهِ ‏ ‏وَنَفْثِهِ ‏ ‏وَنَفْخِهِ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ مَا هَمْزُهُ وَنَفْثُهُ وَنَفْخُهُ قَالَ أَمَّا هَمْزُهُ ‏ ‏فَالْمُوتَةُ الَّتِي تَأْخُذُ ابْنَ ‏ ‏آدَمَ ‏ ‏وَأَمَّا نَفْخُهُ الْكِبْرُ وَنَفْثُهُ الشِّعْرُ ‏","","",""],[16140,16140,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مِسْعَرٌ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏عَنَزَةَ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏اللَّهُ أَكْبَرُ كَبِيرًا وَالْحَمْدُ لِلَّهِ كَثِيرًا وَسُبْحَانَ اللَّهِ بُكْرَةً وَأَصِيلًا اللَّهُمَّ إِنِّي ‏ ‏أَعُوذُ بِكَ مِنْ الشَّيْطَانِ الرَّجِيمِ مِنْ هَمْزِهِ وَنَفْثِهِ وَنَفْخِهِ قَالَ قُلْتُ مَا هَمْزُهُ قَالَ فَذَكَرَ كَهَيْئَةِ ‏ ‏الْمُوتَةِ ‏ ‏يَعْنِي يَصْرَعُ ‏ ‏قُلْتُ فَمَا نَفْخُهُ قَالَ الْكِبْرُ قُلْتُ فَمَا نَفْثُهُ قَالَ الشِّعْرُ ‏","","",""],[16141,16141,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏قَالَ ‏ ‏لَمَّا قَسَمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَهْمَ الْقُرْبَى مِنْ ‏ ‏خَيْبَرَ ‏ ‏بَيْنَ ‏ ‏بَنِي هَاشِمٍ ‏ ‏وَبَنِي الْمُطَّلِبِ ‏ ‏جِئْتُ أَنَا ‏ ‏وَعُثْمَانُ بْنُ عَفَّانَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ هَؤُلَاءِ ‏ ‏بَنُو هَاشِمٍ ‏ ‏لَا يُنْكَرُ فَضْلُهُمْ لِمَكَانِكَ الَّذِي وَصَفَكَ اللَّهُ عَزَّ وَجَلَّ بِهِ مِنْهُمْ أَرَأَيْتَ إِخْوَانَنَا مِنْ ‏ ‏بَنِي الْمُطَّلِبِ ‏ ‏أَعْطَيْتَهُمْ وَتَرَكْتَنَا وَإِنَّمَا نَحْنُ وَهُمْ مِنْكَ بِمَنْزِلَةٍ وَاحِدَةٍ قَالَ ‏ ‏إِنَّهُمْ لَمْ يُفَارِقُونِي فِي جَاهِلِيَّةٍ وَلَا إِسْلَامٍ وَإِنَّمَا هُمْ ‏ ‏بَنُو هَاشِمٍ ‏ ‏وَبَنُو الْمُطَّلِبِ ‏ ‏شَيْءٌ وَاحِدٌ قَالَ ثُمَّ شَبَّكَ بَيْنَ أَصَابِعِهِ ‏","","",""],[16142,16142,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏طَلْحَةَ بْنِ عَبْدِ اللَّهِ بْنِ عَوْفٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْأَزْهَرِ ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ لِلْقُرَشِيِّ مِثْلَيْ قُوَّةِ الرَّجُلِ مِنْ غَيْرِ ‏ ‏قُرَيْشٍ ‏ ‏فَقِيلَ ‏ ‏لِلزُّهْرِيِّ ‏ ‏مَا عَنَى بِذَلِكَ قَالَ نُبْلَ الرَّأْيِ ‏","","",""],[16143,16143,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏قَالَ أَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَبْدَ اللَّهِ بْنَ بَابَيْهِ ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْرُ عَطَاءٍ هَذَا يَا ‏ ‏بَنِي عَبْدِ مَنَافٍ ‏ ‏وَيَا ‏ ‏بَنِي عَبْدِ الْمُطَّلِبِ ‏ ‏إِنْ كَانَ لَكُمْ مِنْ الْأَمْرِ شَيْءٌ فَلَأَعْرِفَنَّ مَا مَنَعْتُمْ أَحَدًا يَطُوفُ بِهَذَا ‏ ‏الْبَيْتِ ‏ ‏أَيَّ سَاعَةٍ مِنْ لَيْلٍ أَوْ نَهَارٍ ‏","","",""],[16144,16144,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زُهَيْرُ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَجُلًا أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ أَيُّ الْبُلْدَانِ شَرٌّ قَالَ فَقَالَ لَا أَدْرِي فَلَمَّا أَتَاهُ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏قَالَ يَا ‏ ‏جِبْرِيلُ ‏ ‏أَيُّ الْبُلْدَانِ شَرٌّ قَالَ لَا أَدْرِي حَتَّى أَسْأَلَ رَبِّي عَزَّ وَجَلَّ فَانْطَلَقَ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏ثُمَّ مَكَثَ مَا شَاءَ اللَّهُ أَنْ يَمْكُثَ ثُمَّ جَاءَ فَقَالَ يَا ‏ ‏مُحَمَّدُ ‏ ‏إِنَّكَ سَأَلْتَنِي أَيُّ الْبُلْدَانِ شَرٌّ فَقُلْتُ لَا أَدْرِي وَإِنِّي ‏ ‏سَأَلْتُ رَبِّي عَزَّ وَجَلَّ أَيُّ الْبُلْدَانِ شَرٌّ فَقَالَ أَسْوَاقُهَا ‏","","",""],[16145,16145,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَنْزِلُ اللَّهُ عَزَّ وَجَلَّ فِي كُلِّ لَيْلَةٍ إِلَى السَّمَاءِ الدُّنْيَا فَيَقُولُ هَلْ مِنْ سَائِلٍ فَأُعْطِيَهُ هَلْ مِنْ مُسْتَغْفِرٍ فَأَغْفِرَ لَهُ حَتَّى يَطْلُعَ الْفَجْرُ ‏","","",""],[16146,16146,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ قَالَ ‏ ‏مَنْ ‏ ‏يَكْلَؤُنَا ‏ ‏اللَّيْلَةَ لَا نَرْقُدُ عَنْ صَلَاةِ الْفَجْرِ فَقَالَ ‏ ‏بِلَالٌ ‏ ‏أَنَا فَاسْتَقْبَلَ مَطْلَعَ الشَّمْسِ فَضُرِبَ عَلَى آذَانِهِمْ فَمَا أَيْقَظَهُمْ إِلَّا حَرُّ الشَّمْسِ فَقَامُوا فَأَدَّوْهَا ثُمَّ تَوَضَّئُوا فَأَذَّنَ ‏ ‏بِلَالٌ ‏ ‏فَصَلَّوْا الرَّكْعَتَيْنِ ثُمَّ صَلَّوْا الْفَجْرَ ‏","","",""],[16147,16147,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَنْزِلُ اللَّهُ عَزَّ وَجَلَّ كُلَّ لَيْلَةٍ إِلَى سَمَاءِ الدُّنْيَا فَيَقُولُ هَلْ مِنْ سَائِلٍ فَأُعْطِيَهُ هَلْ مِنْ مُسْتَغْفِرٍ فَأَغْفِرَ لَهُ ‏","","",""],[16148,16148,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ أَبِي وَحْشِيَّةَ ‏ ‏وَقَالَ ‏ ‏أَحَدُهُمَا ‏ ‏جَعْفَرُ بْنُ إِيَاسٍ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَنَا ‏ ‏مُحَمَّدٌ ‏ ‏وَأَحْمَدُ ‏ ‏وَالْحَاشِرُ ‏ ‏وَالْمَاحِي ‏ ‏وَالْخَاتِمُ ‏ ‏وَالْعَاقِبُ ‏","","",""],[16149,16149,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنُ بْنُ الْمُثَنَّى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ صُرَدٍ ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏قَالَ ‏ ‏تَذَاكَرْنَا غُسْلَ ‏ ‏الْجَنَابَةِ ‏ ‏عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَّا أَنَا فَآخُذُ مِلْءَ كَفِّي ثَلَاثًا فَأَصُبُّ عَلَى رَأْسِي ثُمَّ ‏ ‏أُفِيضُ ‏ ‏بَعْدُ عَلَى سَائِرِ جَسَدِي ‏","","",""],[16150,16150,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ كَثِيرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ كَثِيرٍ ‏ ‏عَنْ ‏ ‏حُصَيْنِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏انْشَقَّ الْقَمَرُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصَارَ فِرْقَتَيْنِ فِرْقَةً عَلَى هَذَا الْجَبَلِ وَفِرْقَةً عَلَى هَذَا الْجَبَلِ فَقَالُوا سَحَرَنَا ‏ ‏مُحَمَّدٌ ‏ ‏فَقَالُوا إِنْ كَانَ سَحَرَنَا فَإِنَّهُ لَا يَسْتَطِيعُ أَنْ يَسْحَرَ النَّاسَ كُلَّهُمْ ‏","","",""],[16151,16151,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عَبْدِ الْعَزِيزِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سُلَيْمَانُ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كُلُّ ‏ ‏عَرَفَاتٍ ‏ ‏مَوْقِفٌ وَارْفَعُوا عَنْ بَطْنِ ‏ ‏عُرَنَةَ ‏ ‏وَكُلُّ ‏ ‏مُزْدَلِفَةَ ‏ ‏مَوْقِفٌ وَارْفَعُوا عَنْ ‏ ‏مُحَسِّرٍ ‏ ‏وَكُلُّ ‏ ‏فِجَاجِ ‏ ‏مِنًى ‏ ‏مَنْحَرٌ ‏ ‏وَكُلُّ ‏ ‏أَيَّامِ التَّشْرِيقِ ‏ ‏ذَبْحٌ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عَبْدِ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ مُوسَى ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مِثْلَهُ وَقَالَ كُلُّ أَيَّامِ التَّشْرِيقِ ذَبْحٌ ‏","","",""],[16152,16152,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ بَابَاهُ ‏ ‏مَوْلَى آلِ ‏ ‏حُجَيْرِ بْنِ أَبِي إِهَابٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جُبَيْرَ بْنَ مُطْعِمٍ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ يَا ‏ ‏بَنِي عَبْدِ مَنَافٍ ‏ ‏لَأَعْرِفَنَّ مَا مَنَعْتُمْ طَائِفًا يَطُوفُ بِهَذَا ‏ ‏الْبَيْتِ ‏ ‏سَاعَةً مِنْ لَيْلٍ أَوْ نَهَارٍ ‏","","",""],[16153,16153,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ فَذَكَرَ ‏ ‏مُحَمَّدُ بْنُ مُسْلِمِ بْنِ عُبَيْدِ اللَّهِ بْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏جُبَيْرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَخْطُبُ النَّاسَ ‏ ‏بِالْخَيْفِ ‏ ‏نَضَّرَ اللَّهُ عَبْدًا سَمِعَ مَقَالَتِي فَوَعَاهَا ثُمَّ أَدَّاهَا لِمَنْ لَمْ يَسْمَعْهَا فَرُبَّ حَامِلِ فِقْهٍ لَا فِقْهَ لَهُ وَرُبَّ حَامِلِ فِقْهٍ إِلَى مَنْ هُوَ أَفْقَهُ مِنْهُ ثَلَاثٌ لَا يَغِلُّ عَلَيْهِنَّ قَلْبُ الْمُؤْمِنِ إِخْلَاصُ الْعَمَلِ وَطَاعَةُ ذَوِي الْأَمْرِ وَلُزُومُ الْجَمَاعَةِ فَإِنَّ دَعْوَتَهُمْ تَكُونُ مِنْ وَرَائِهِ ‏ ‏و عَنْ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَمْرُو بْنُ أَبِي عَمْرٍو ‏ ‏مَوْلَى ‏ ‏الْمُطَّلِبِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْحُوَيْرِثِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏مِثْلَ حَدِيثِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏لَمْ يَزِدْ وَلَمْ يَنْقُصْ ‏","","",""],[16154,16154,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مُحَمَّدُ بْنُ جُبَيْرٍ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏جُبَيْرَ بْنَ مُطْعِمٍ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ امْرَأَةً أَتَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَكَلَّمَتْهُ فِي شَيْءٍ فَأَمَرَهَا بِأَمْرٍ فَقَالَتْ أَرَأَيْتَ يَا رَسُولَ اللَّهِ إِنْ لَمْ أَجِدْكَ قَالَ ‏ ‏إِنْ لَمْ تَجِدِينِي فَأْتِي ‏ ‏أَبَا بَكْرٍ ‏","","",""],[16155,16155,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏أَخْبَرَنِي ‏ ‏عُمَرُ بْنُ مُحَمَّدِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏أَنَّ ‏ ‏مُحَمَّدَ بْنَ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏جُبَيْرُ بْنُ مُطْعِمٍ ‏ ‏أَنَّهُ ‏ ‏بَيْنَا هُوَ يَسِيرُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَعَهُ النَّاسُ مُقْبِلًا مِنْ ‏ ‏حُنَيْنٍ ‏ ‏عَلِقَتْ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْأَعْرَابُ ‏ ‏يَسْأَلُونَهُ حَتَّى اضْطَرُّوهُ إِلَى ‏ ‏سَمُرَةٍ ‏ ‏فَخَطِفَتْ ‏ ‏رِدَاءَهُ ‏ ‏فَوَقَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ ‏ ‏أَعْطُونِي رِدَائِي فَلَوْ كَانَ عَدَدُ هَذِهِ ‏ ‏الْعِضَاهِ ‏ ‏نَعَمًا لَقَسَمْتُهُ ثُمَّ لَا تَجِدُونِي بَخِيلًا وَلَا كَذَّابًا وَلَا جَبَانًا ‏","","",""],[16156,16156,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي بَكْرِ بْنِ مُحَمَّدِ بْنِ عَمْرِو بْنِ حَزْمٍ الْأَنْصَارِيُّ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ أَبِي سُلَيْمَانَ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏نَافِعِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏جُبَيْرٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَبْلَ أَنْ يُنَزَّلَ عَلَيْهِ وَإِنَّهُ ‏ ‏لَوَاقِفٌ عَلَى بَعِيرٍ لَهُ ‏ ‏بِعَرَفَاتٍ ‏ ‏مَعَ النَّاسِ حَتَّى يَدْفَعَ مَعَهُمْ مِنْهَا تَوْفِيقًا مِنْ اللَّهِ لَهُ ‏","","",""],[16157,16157,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَ أَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ يَزِيدَ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ أَبِي ذُبَابٍ ‏ ‏إِنْ شَاءَ اللَّهُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَفَعَ رَأْسَهُ إِلَى السَّمَاءِ فَقَالَ ‏ ‏أَتَاكُمْ أَهْلُ ‏ ‏الْيَمَنِ ‏ ‏كَقِطَعِ السَّحَابِ خَيْرُ أَهْلِ الْأَرْضِ فَقَالَ لَهُ رَجُلٌ مِمَّنْ كَانَ عِنْدَهُ وَمِنَّا يَا رَسُولَ اللَّهِ قَالَ كَلِمَةً خَفِيَّةً إِلَّا أَنْتُمْ ‏","","",""],[16158,16158,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏النُّعْمَانُ بْنُ سَالِمٍ ‏ ‏أَخْبَرَنِي عَنْ ‏ ‏رَجُلٍ ‏ ‏سَمَّاهُ ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏قَالَ أُرَاهُ قَدْ سَمِعَهُ مِنْ ‏ ‏جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ إِنَّ النَّاسَ يَزْعُمُونَ أَنَّهُ لَيْسَ لَنَا أُجُورٌ ‏ ‏بِمَكَّةَ ‏ ‏قَالَ ‏ ‏فَأَحْسَبُهُ قَالَ ‏ ‏كَذَبُوا لَتَأْتِيَنَّكُمْ أُجُورُكُمْ وَلَوْ كُنْتُمْ فِي جُحْرِ ثَعْلَبٍ ‏","","",""],[16159,16159,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏عَبْد اللَّهِ بْن أَحْمَد ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ إِدْرِيسَ ‏ ‏عَنْ ‏ ‏حُصَيْنٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ عَاصِمٍ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ افْتَتَحَ الصَّلَاةَ قَالَ ‏ ‏اللَّهُ أَكْبَرُ كَبِيرًا ثَلَاثًا الْحَمْدُ لِلَّهِ كَثِيرًا ثَلَاثًا سُبْحَانَ اللَّهِ بُكْرَةً وَأَصِيلًا ثَلَاثًا اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ الشَّيْطَانِ مِنْ ‏ ‏هَمْزِهِ ‏ ‏وَنَفْثِهِ ‏ ‏وَنَفْخِهِ ‏ ‏قَالَ ‏ ‏حُصَيْنٌ ‏ ‏هَمْزُهُ ‏ ‏الْمُوتَةُ الَّتِي تَأْخُذُ صَاحِبَ الْمَسِّ وَنَفْثُهُ الشِّعْرُ وَنَفْخُهُ الْكِبْرُ ‏","","",""],[16160,16160,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏وَأَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏زَكَرِيَّا ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا حِلْفَ فِي الْإِسْلَامِ وَأَيُّمَا حِلْفٍ كَانَ فِي الْجَاهِلِيَّةِ لَمْ يَزِدْهُ الْإِسْلَامُ إِلَّا شِدَّةً ‏","","",""],[16161,16161,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏وَمُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏بَعْضَ إِخْوَتِي ‏ ‏عَنْ ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏أَنَّهُ ‏ ‏أَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي فِدَاءِ ‏ ‏بَدْرٍ ‏ ‏قَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏فِي فِدَاءِ الْمُشْرِكِينَ ‏ ‏وَمَا أَسْلَمَ يَوْمَئِذٍ فَدَخَلْتُ الْمَسْجِدَ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي الْمَغْرِبَ فَقَرَأَ ‏ ‏بِالطُّورِ ‏ ‏فَكَأَنَّمَا ‏ ‏صُدِعَ ‏ ‏عَنْ قَلْبِي حِينَ سَمِعْتُ الْقُرْآنَ ‏ ‏قَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏فَكَأَنَّمَا ‏ ‏صُدِعَ ‏ ‏قَلْبِي حَيْثُ سَمِعْتُ الْقُرْآنَ ‏","","",""],[16162,16162,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَنَا ‏ ‏سُفْيَانُ يَعْنِي ابْنَ حُسَيْنٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الزُّهْرِيَّ ‏ ‏حَدَّثَ عَنْ ‏ ‏مُحَمَّدِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَدْخُلُ الْجَنَّةَ ‏ ‏قَاطِعٌ ‏","","",""],[16163,16163,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ سَالِمٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ إِنَّهُمْ يَزْعُمُونَ أَنَّهُ لَيْسَ لَنَا أَجْرٌ ‏ ‏بِمَكَّةَ ‏ ‏قَالَ ‏ ‏لَتَأْتِيَنَّكُمْ أُجُورُكُمْ وَلَوْ كُنْتُمْ فِي ‏ ‏جُحْرِ ‏ ‏ثَعْلَبٍ قَالَ ‏ ‏فَأَصْغَى ‏ ‏إِلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِرَأْسِهِ فَقَالَ إِنَّ فِي أَصْحَابِي مُنَافِقِينَ ‏","","",""],[16164,16164,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَدِمْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي فِدَاءِ أَهْلِ ‏ ‏بَدْرٍ ‏ ‏فَقَامَ ‏ ‏فَصَلَّى بِالنَّاسِ صَلَاةَ الْمَغْرِبِ فَقَرَأَ ‏ ‏بِالطُّورِ ‏","","",""],[16165,16165,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏طَلْحَةَ بْنِ عَبْدِ اللَّهِ بْنِ عَوْفٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْأَزْهَرِ ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ لِلْقُرَشِيِّ مِثْلَيْ قُوَّةِ الرَّجُلِ مِنْ غَيْرِ ‏ ‏قُرَيْشٍ ‏ ‏فَقِيلَ ‏ ‏لِلزُّهْرِيِّ ‏ ‏مَا ‏ ‏يَعْنِي بِذَلِكَ قَالَ نُبْلَ الرَّأْيِ ‏","","",""],[16166,16166,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ امْرَأَةً أَتَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَسْأَلُهُ شَيْئًا فَقَالَ لَهَا ارْجِعِي إِلَيَّ فَقَالَتْ فَإِنْ رَجَعْتُ فَلَمْ أَجِدْكَ يَا رَسُولَ اللَّهِ ‏ ‏تُعَرِّضُ ‏ ‏بِالْمَوْتِ فَقَالَ لَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِنْ رَجَعْتِ فَلَمْ تَجِدِينِي فَالْقَيْ ‏ ‏أَبَا بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏","","",""],[16167,16167,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جُبَيْرُ بْنُ مُطْعِمٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يَقْسِمْ ‏ ‏لِعَبْدِ شَمْسٍ ‏ ‏وَلَا ‏ ‏لِبَنِي نَوْفَلٍ ‏ ‏مِنْ ‏ ‏الْخُمُسِ ‏ ‏شَيْئًا كَمَا كَانَ يَقْسِمُ ‏ ‏لِبَنِي هَاشِمٍ ‏ ‏وَبَنِي الْمُطَّلِبِ ‏ ‏وَأَنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏كَانَ يَقْسِمُ ‏ ‏الْخُمُسَ ‏ ‏نَحْوَ قَسْمِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَيْرَ أَنَّهُ لَمْ يَكُنْ يُعْطِي ‏ ‏قُرْبَى ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَمَا كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعْطِيهِمْ ‏ ‏وَكَانَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يُعْطِيهِمْ ‏ ‏وَعُثْمَانُ ‏ ‏مِنْ بَعْدِهِ مِنْهُ ‏","","",""],[16168,16168,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ بَابَيْهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جُبَيْرَ بْنَ مُطْعِمٍ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَأَعْرِفَنَّ يَا ‏ ‏بَنِي عَبْدِ مَنَافٍ ‏ ‏مَا مَنَعْتُمْ طَائِفًا يَطُوفُ بِهَذَا ‏ ‏الْبَيْتِ ‏ ‏سَاعَةً مِنْ لَيْلٍ أَوْ نَهَارٍ ‏","","",""],[16169,16169,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزُ بْنُ أَسَدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ أَبِي وَحْشِيَّةَ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَنَا ‏ ‏مُحَمَّدٌ ‏ ‏وَأَحْمَدُ ‏ ‏وَالْحَاشِرُ ‏ ‏وَالْمَاحِي ‏ ‏وَالْخَاتِمُ ‏ ‏وَالْعَاقِبُ ‏","","",""],[16170,16170,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ إِنَّ لِي أَسْمَاءً ‏ ‏أَنَا ‏ ‏أَحْمَدُ ‏ ‏وَأَنَا ‏ ‏مُحَمَّدٌ ‏ ‏وَأَنَا ‏ ‏الْمَاحِي ‏ ‏الَّذِي يَمْحُو اللَّهُ بِي الْكُفْرَ وَأَنَا ‏ ‏الْحَاشِرُ ‏ ‏الَّذِي يُحْشَرُ النَّاسُ عَلَى قَدَمِي وَأَنَا ‏ ‏الْعَاقِبُ ‏ ‏قَالَ ‏ ‏مَعْمَرٌ ‏ ‏قُلْتُ ‏ ‏لِلزُّهْرِيِّ ‏ ‏مَا ‏ ‏الْعَاقِبُ ‏ ‏قَالَ الَّذِي لَيْسَ بَعْدَهُ نَبِيٌّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[16171,16171,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَدْخُلُ الْجَنَّةَ ‏ ‏قَاطِعٌ ‏","","",""],[16172,16172,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏وَكَانَ جَاءَ فِي فِدَاءِ الْأُسَارَى يَوْمَ ‏ ‏بَدْرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ فِي الْمَغْرِبِ ‏ ‏بِالطُّورِ ‏","","",""],[16173,16173,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَبْدَ اللَّهِ بْنَ بَابَاهُ ‏ ‏يُخْبِرُ عَنْ ‏ ‏جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ عَطَاءِ هَدَايَا ‏ ‏بَنِي عَبْدِ الْمُطَّلِبِ ‏ ‏يَا ‏ ‏بَنِي عَبْدِ مَنَافٍ ‏ ‏إِنْ كَانَ إِلَيْكُمْ مِنْ الْأَمْرِ شَيْءٌ ‏ ‏فَلَأَعْرِفَنَّ مَا مَنَعْتُمْ أَحَدًا ‏ ‏يُصَلِّي عِنْدَ هَذَا ‏ ‏الْبَيْتِ ‏ ‏أَيَّ سَاعَةٍ شَاءَ مِنْ لَيْلٍ أَوْ نَهَارٍ ‏ ‏وَقَالَ ‏ ‏ابْنُ بَكْرٍ ‏ ‏أَنْ يَطُوفَ بِهَذَا ‏ ‏الْبَيْتِ ‏","","",""],[16174,16174,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ مُحَمَّدِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏أَخْبَرَهُ ‏ ‏بَيْنَا هُوَ يَسِيرُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَعَهُ نَاسٌ ‏ ‏مَقْفَلَهُ ‏ ‏مِنْ ‏ ‏حُنَيْنٍ ‏ ‏عَلِقَهُ ‏ ‏الْأَعْرَابُ ‏ ‏يَسْأَلُونَهُ فَاضْطَرُّوهُ إِلَى ‏ ‏سَمُرَةٍ ‏ ‏فَخَطِفَتْ ‏ ‏رِدَاءَهُ ‏ ‏وَهُوَ عَلَى ‏ ‏رَاحِلَتِهِ ‏ ‏فَوَقَفَ فَقَالَ ‏ ‏رُدُّوا عَلَيَّ ‏ ‏رِدَائِي ‏ ‏أَتَخْشَوْنَ عَلَيَّ الْبُخْلَ فَلَوْ كَانَ عَدَدُ هَذِهِ ‏ ‏الْعِضَاهِ ‏ ‏نَعَمًا لَقَسَمْتُهُ بَيْنَكُمْ ثُمَّ لَا تَجِدُونِي بَخِيلًا وَلَا جَبَانًا وَلَا كَذَّابًا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏أَخْطَأَ ‏ ‏مَعْمَرٌ ‏ ‏فِي نَسَبِ ‏ ‏عُمَرَ بْنِ مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏وَهُوَ ‏ ‏عُمَرُ بْنُ مُحَمَّدِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏","","",""],[16175,16175,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏قَالَ أَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏قَالَ ‏ ‏أَضْلَلْتُ جَمَلًا لِي يَوْمَ ‏ ‏عَرَفَةَ ‏ ‏فَانْطَلَقْتُ إِلَى ‏ ‏عَرَفَةَ ‏ ‏أَبْتَغِيهِ ‏ ‏فَإِذَا أَنَا ‏ ‏بِمُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاقِفٌ فِي النَّاسِ ‏ ‏بِعَرَفَةَ ‏ ‏عَلَى بَعِيرِهِ عَشِيَّةَ ‏ ‏عَرَفَةَ ‏ ‏وَذَلِكَ بَعْدَمَا أُنْزِلَ عَلَيْهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ أَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُمَرُ بْنُ مُحَمَّدِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏أَنَّ ‏ ‏مُحَمَّدَ بْنَ جُبَيْرٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏جُبَيْرُ بْنُ مُطْعِمٍ ‏ ‏أَنَّهُ ‏ ‏بَيْنَا هُوَ يَسِيرُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏يَعْنِي نَحْوَ حَدِيثِ ‏ ‏مَعْمَرٍ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَخِي ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُمَرُ بْنُ مُحَمَّدِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏أَنَّ ‏ ‏مُحَمَّدَ بْنَ جُبَيْرٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏جُبَيْرُ بْنُ مُطْعِمٍ ‏ ‏أَنَّهُ ‏ ‏بَيْنَا هُوَ يَسِيرُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَقْفَلَهُ مِنْ ‏ ‏حُنَيْنٍ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[16176,16176,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏بَيْنَا نَحْنُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِطَرِيقِ ‏ ‏مَكَّةَ ‏ ‏إِذْ قَالَ ‏ ‏يَطْلُعُ عَلَيْكُمْ أَهْلُ ‏ ‏الْيَمَنِ ‏ ‏كَأَنَّهُمْ السَّحَابُ هُمْ خِيَارُ مَنْ فِي الْأَرْضِ فَقَالَ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏وَلَا نَحْنُ يَا رَسُولَ اللَّهِ فَسَكَتَ قَالَ وَلَا نَحْنُ يَا رَسُولَ اللَّهِ فَسَكَتَ قَالَ وَلَا نَحْنُ يَا رَسُولَ اللَّهِ فَقَالَ فِي الثَّالِثَةِ كَلِمَةً ضَعِيفَةً إِلَّا أَنْتُمْ ‏","","",""],[16177,16177,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعُ ‏ ‏وَعَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ صُرَدٍ ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏قَالَ ‏ ‏تَذَاكَرْنَا الْغُسْلَ مِنْ ‏ ‏الْجَنَابَةِ ‏ ‏عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أَمَّا أَنَا ‏ ‏فَأُفِيضُ ‏ ‏عَلَى رَأْسِي ثَلَاثًا ‏ ‏وَقَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏ذُكِرَتْ ‏ ‏الْجَنَابَةُ ‏ ‏عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَمَّا أَنَا فَآخُذُ بِكَفِّي ثَلَاثًا ‏ ‏فَأُفِيضُ ‏ ‏عَلَى رَأْسِي ‏","","",""],[16178,16178,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏النُّعْمَانُ بْنُ سَالِمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏إِنْسَانًا ‏ ‏لَا أَحْفَظُ اسْمَهُ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ إِنَّ أُنَاسًا يَزْعُمُونَ أَنَّهُ لَيْسَتْ لَنَا أُجُورٌ ‏ ‏بِمَكَّةَ ‏ ‏قَالَ ‏ ‏لَتَأْتِيَنَّكُمْ أُجُورُكُمْ وَلَوْ كَانَ أَحَدُكُمْ فِي جُحْرِ ثَعْلَبٍ ‏","","",""],[16179,16179,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏يُونُسَ بْنِ يَزِيدَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏سَعِيدُ بْنُ الْمُسَيَّبِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏جُبَيْرُ بْنُ مُطْعِمٍ ‏ ‏أَنَّهُ جَاءَ ‏ ‏وَعُثْمَانُ بْنُ عَفَّانَ ‏ ‏يُكَلِّمَانِ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيمَا قَسَمَ مِنْ ‏ ‏خُمُسِ ‏ ‏حُنَيْنٍ ‏ ‏بَيْنَ ‏ ‏بَنِي هَاشِمٍ ‏ ‏وَبَنِي الْمُطَّلِبِ ‏ ‏فَقَالَا يَا رَسُولَ اللَّهِ قَسَمْتَ لِإِخْوَانِنَا ‏ ‏بَنِي الْمُطَّلِبِ ‏ ‏وَبَنِي عَبْدِ مَنَافٍ ‏ ‏وَلَمْ تُعْطِنَا شَيْئًا وَقَرَابَتُنَا مِثْلُ قَرَابَتِهِمْ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا أَرَى ‏ ‏هَاشِمًا ‏ ‏وَالْمُطَّلِبَ ‏ ‏شَيْئًا وَاحِدًا قَالَ ‏ ‏جُبَيْرٌ ‏ ‏وَلَمْ يَقْسِمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِبَنِي عَبْدِ شَمْسٍ ‏ ‏وَلَا ‏ ‏لِبَنِي نَوْفَلٍ ‏ ‏مِنْ ذَلِكَ ‏ ‏الْخُمُسِ ‏ ‏كَمَا قَسَمَ ‏ ‏لِبَنِي هَاشِمٍ ‏ ‏وَبَنِي الْمُطَّلِبِ ‏","","",""],[16180,16180,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏وَحَدَّثَنِي ‏ ‏حَمَّادٌ الْخَيَّاطُ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَرَأَ ‏ ‏بِالطُّورِ ‏ ‏فِي الْمَغْرِبِ ‏ ‏وَقَالَ ‏ ‏حَمَّادٌ ‏ ‏إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَرَأَ ‏","","",""],[16181,16181,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏عَاصِمٍ الْعَنَزِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏و قَالَ ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ دَخَلَ فِي صَلَاةٍ فَقَالَ ‏ ‏اللَّهُ أَكْبَرُ كَبِيرًا اللَّهُ أَكْبَرُ كَبِيرًا اللَّهُ أَكْبَرُ كَبِيرًا الْحَمْدُ لِلَّهِ بُكْرَةً ‏ ‏وَأَصِيلًا ‏ ‏ثَلَاثًا سُبْحَانَ اللَّهِ بُكْرَةً ‏ ‏وَأَصِيلًا ‏ ‏ثَلَاثًا اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ الشَّيْطَانِ الرَّجِيمِ مِنْ ‏ ‏هَمْزِهِ ‏ ‏وَنَفْخِهِ ‏ ‏وَنَفْثِهِ ‏ ‏قَالَ ‏ ‏عُمَرُ ‏ ‏وَهَمْزُهُ ‏ ‏الْمُوتَةُ وَنَفْخُهُ الْكِبْرُ وَنَفْثُهُ الشِّعْرُ ‏","","",""],[16182,16182,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏بَعْضَ إِخْوَتِي ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏أَنَّهُ أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي فِدَاءِ الْمُشْرِكِينَ ‏ ‏وَقَالَ ‏ ‏بَهْزٌ ‏ ‏فِي فِدَاءِ أَهْلِ ‏ ‏بَدْرٍ ‏ ‏وَقَالَ ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَمَا أَسْلَمَ يَوْمَئِذٍ ‏ ‏قَالَ فَانْتَهَيْتُ إِلَيْهِ وَهُوَ ‏ ‏يُصَلِّي الْمَغْرِبَ وَهُوَ يَقْرَأُ فِيهَا ‏ ‏بِالطُّورِ ‏ ‏قَالَ فَكَأَنَّمَا ‏ ‏صُدِعَ ‏ ‏قَلْبِي حَيْثُ سَمِعْتُ الْقُرْآنَ ‏ ‏وَقَالَ ‏ ‏بَهْزٌ ‏ ‏فِي حَدِيثِهِ فَكَأَنَّمَا ‏ ‏صُدِعَ ‏ ‏قَلْبِي حِينَ سَمِعْتُ الْقُرْآنَ ‏","","",""],[16183,16183,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا إِسْحَاقَ ‏ ‏يُحَدِّثُ أَنَّهُ سَمِعَ ‏ ‏سُلَيْمَانَ بْنَ صُرَدٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ذُكِرَ عِنْدَهُ الْغُسْلُ مِنْ الْجَنَابَةِ فَقَالَ ‏ ‏أَمَّا أَنَا فَأُفْرِغُ عَلَى رَأْسِي ثَلَاثًا ‏","","",""],[16184,16184,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ إِيَاسٍ الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ عَبَايَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ يَزِيدَ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏سَمِعَنِي ‏ ‏أَبِي ‏ ‏وَأَنَا أَقُولُ ‏ { ‏بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ ‏} ‏فَقَالَ أَيْ بُنَيَّ إِيَّاكَ قَالَ وَلَمْ أَرَ أَحَدًا مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ أَبْغَضَ إِلَيْهِ حَدَثًا فِي الْإِسْلَامِ مِنْهُ فَإِنِّي قَدْ ‏ ‏صَلَّيْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَعَ ‏ ‏أَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏وَمَعَ ‏ ‏عُثْمَانَ ‏ ‏فَلَمْ أَسْمَعْ أَحَدًا مِنْهُمْ يَقُولُهَا فَلَا تَقُلْهَا إِذَا أَنْتَ قَرَأْتَ فَقُلْ ‏ { ‏الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ‏}","","",""],[16185,16185,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْلَا أَنَّ الْكِلَابَ أُمَّةٌ مِنْ الْأُمَمِ لَأَمَرْتُ بِقَتْلِهَا فَاقْتُلُوا مِنْهَا الْأَسْوَدَ ‏ ‏الْبَهِيمَ ‏ ‏وَأَيُّمَا قَوْمٍ اتَّخَذُوا كَلْبًا لَيْسَ بِكَلْبِ حَرْثٍ أَوْ صَيْدٍ أَوْ مَاشِيَةٍ نَقَصُوا مِنْ أُجُورِهِمْ كُلَّ يَوْمٍ ‏ ‏قِيرَاطًا ‏","","",""],[16186,16186,"","","‏ ‏قَالَ ‏ ‏وَكُنَّا نُؤْمَرُ أَنْ نُصَلِّيَ فِي ‏ ‏مَرَابِضِ ‏ ‏الْغَنَمِ وَلَا نُصَلِّيَ فِي ‏ ‏أَعْطَانِ ‏ ‏الْإِبِلِ فَإِنَّهَا خُلِقَتْ مِنْ الشَّيَاطِينِ ‏","","",""],[16187,16187,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ إِدْرِيسَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏شُعْبَةَ ‏ ‏يَذْكُرُ عَنْ ‏ ‏أَبِي إِيَاسٍ مُعَاوِيَةَ بْنِ قُرَّةَ الْمُزَنِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُهُ يَقْرَأُ ‏ ‏يَعْنِي النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ الْفَتْحِ ‏ ‏فَلَوْلَا أَنْ يَجْتَمِعَ النَّاسُ عَلَيَّ لَحَكَيْتُ ‏ ‏لَكُمْ قِرَاءَةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قَرَأَ سُورَةَ ‏ ‏الْفَتْحِ ‏ ‏قَالَ لَوْلَا أَنْ يَجْتَمِعَ النَّاسُ عَلَيَّ لَحَكَيْتُ لَكُمْ مَا قَالَ ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ مُغَفَّلٍ ‏ ‏كَيْفَ قَرَأَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏و قَالَ ‏ ‏بَهْزٌ ‏ ‏وَغُنْدَرٌ ‏ ‏قَالَ ‏ ‏فَرَجَّعَ فِيهَا ‏","","",""],[16188,16188,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏كَهْمَسٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ بُرَيْدَةَ ‏ ‏عَنِ ‏ ‏ابْنِ مُغَفَّلٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بَيْنَ كُلِّ أَذَانَيْنِ صَلَاةٌ لِمَنْ شَاءَ ‏","","",""],[16189,16189,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ الْمُغِيرَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حُمَيْدُ بْنُ هِلَالٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُغَفَّلٍ ‏ ‏قَالَ قَالَ ‏ ‏دُلِّيَ ‏ ‏جِرَابٌ ‏ ‏مِنْ شَحْمٍ يَوْمَ ‏ ‏خَيْبَرَ ‏ ‏قَالَ فَالْتَزَمْتُهُ قُلْتُ لَا أُعْطِي أَحَدًا مِنْهُ شَيْئًا قَالَ فَالْتَفَتُّ فَإِذَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَبَسَّمُ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏إِلَيَّ ‏","","",""],[16190,16190,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو التَّيَّاحِ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنِ ‏ ‏ابْنِ مُغَفَّلٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ بِقَتْلِ الْكِلَابِ ثُمَّ قَالَ مَا لَهُمْ وَلَهَا فَرَخَّصَ فِي كَلْبِ الصَّيْدِ وَفِي كَلْبِ الْغَنَمِ قَالَ وَإِذَا ‏ ‏وَلَغَ ‏ ‏الْكَلْبُ فِي الْإِنَاءِ فَاغْسِلُوهُ سَبْعَ مِرَارٍ وَالثَّامِنَةَ ‏ ‏عَفِّرُوهُ ‏ ‏بِالتُّرَابِ ‏","","",""],[16191,16191,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْحَسَنَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ الْمُزَنِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏التَّرَجُّلِ ‏ ‏إِلَّا ‏ ‏غِبًّا ‏","","",""],[16192,16192,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏كَهْمَسٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ بُرَيْدَةَ ‏ ‏عَنِ ‏ ‏ابْنِ مُغَفَّلٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْخَذْفِ ‏ ‏وَقَالَ إِنَّهَا لَا ‏ ‏يُنْكَأُ ‏ ‏بِهَا عَدُوٌّ وَلَا يُصَادُ بِهَا صَيْدٌ ‏","","",""],[16193,16193,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَاصِمٌ الْأَحْوَلُ ‏ ‏عَنِ ‏ ‏فُضَيْلِ بْنِ زَيْدٍ الرَّقَاشِيِّ ‏ ‏قَالَ ‏ ‏كُنَّا عِنْدَ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ ‏ ‏قَالَ فَتَذَاكَرْنَا الشَّرَابَ فَقَالَ الْخَمْرُ حَرَامٌ قُلْتُ لَهُ الْخَمْرُ حَرَامٌ فِي كِتَابِ اللَّهِ عَزَّ وَجَلَّ قَالَ ‏ ‏إِيشْ تُرِيدُ تُرِيدُ مَا سَمِعْتُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْهَى عَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالْحَنْتَمِ ‏ ‏وَالْمُزَفَّتِ ‏ ‏قَالَ ‏ ‏قُلْتُ مَا ‏ ‏الْحَنْتَمُ ‏ ‏قَالَ ‏ ‏كُلُّ خَضْرَاءَ وَبَيْضَاءَ قَالَ قُلْتُ مَا ‏ ‏الْمُزَفَّتُ ‏ ‏قَالَ كُلُّ ‏ ‏مُقَيَّرٍ ‏ ‏مِنْ ‏ ‏زِقٍّ ‏ ‏أَوْ غَيْرِهِ ‏","","",""],[16194,16194,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ الرَّقَاشِيِّ ‏ ‏عَنْ ‏ ‏أَبِي نَعَامَةَ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ مُغَفَّلٍ ‏ ‏سَمِعَ ابْنًا لَهُ يَقُولُ اللَّهُمَّ إِنِّي أَسْأَلُكَ الْفِرْدَوْسَ وَكَذَا وَأَسْأَلُكَ كَذَا فَقَالَ أَيْ بُنَيَّ سَلْ اللَّهَ الْجَنَّةَ وَتَعَوَّذْ بِاللَّهِ مِنْ النَّارِ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يَكُونُ فِي هَذِهِ الْأُمَّةِ قَوْمٌ ‏ ‏يَعْتَدُونَ ‏ ‏فِي الدُّعَاءِ وَالطَّهُورِ ‏","","",""],[16195,16195,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَعَبْدُ الْأَعْلَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَقْطَعُ الصَّلَاةَ الْمَرْأَةُ وَالْكَلْبُ وَالْحِمَارُ ‏","","",""],[16196,16196,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْمُبَارَكُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ تَبِعَ جِنَازَةً حَتَّى يُصَلِّيَ عَلَيْهَا فَلَهُ قِيرَاطٌ وَمَنْ انْتَظَرَهَا حَتَّى يُفْرَغَ مِنْهَا فَلَهُ قِيرَاطَانِ ‏","","",""],[16197,16197,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْمُبَارَكُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلُّوا فِي ‏ ‏مَرَابِضِ ‏ ‏الْغَنَمِ وَلَا تُصَلُّوا فِي ‏ ‏أَعْطَانِ ‏ ‏الْإِبِلِ فَإِنَّهَا خُلِقَتْ مِنْ الشَّيَاطِينِ ‏","","",""],[16198,16198,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏حُسَيْنُ بْنُ وَاقِدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ثَابِتٌ الْبُنَانِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ الْمُزَنِيِّ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْحُدَيْبِيَةِ ‏ ‏فِي أَصْلِ الشَّجَرَةِ الَّتِي قَالَ اللَّهُ تَعَالَى فِي الْقُرْآنِ وَكَانَ يَقَعُ مِنْ أَغْصَانِ تِلْكَ الشَّجَرَةِ عَلَى ظَهْرِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَلِيُّ بْنُ أَبِي طَالِبٍ ‏ ‏وَسُهَيْلُ بْنُ عَمْرٍو ‏ ‏بَيْنَ يَدَيْهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِعَلِيٍّ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏اكْتُبْ بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ فَأَخَذَ ‏ ‏سُهَيْلُ بْنُ عَمْرٍو ‏ ‏بِيَدِهِ فَقَالَ مَا نَعْرِفُ بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ اكْتُبْ فِي قَضِيَّتِنَا مَا نَعْرِفُ قَالَ اكْتُبْ بِاسْمِكَ اللَّهُمَّ فَكَتَبَ هَذَا ‏ ‏مَا صَالَحَ عَلَيْهِ ‏ ‏مُحَمَّدٌ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَهْلَ ‏ ‏مَكَّةَ ‏ ‏فَأَمْسَكَ ‏ ‏سُهَيْلُ بْنُ عَمْرٍو ‏ ‏بِيَدِهِ وَقَالَ لَقَدْ ظَلَمْنَاكَ إِنْ كُنْتَ رَسُولَهُ اكْتُبْ فِي قَضِيَّتِنَا مَا نَعْرِفُ فَقَالَ اكْتُبْ هَذَا مَا صَالَحَ عَلَيْهِ ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ عَبْدِ الْمُطَّلِبِ ‏ ‏وَأَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَكَتَبَ فَبَيْنَا نَحْنُ كَذَلِكَ إِذْ خَرَجَ عَلَيْنَا ثَلَاثُونَ شَابًّا عَلَيْهِمْ السِّلَاحُ فَثَارُوا فِي وُجُوهِنَا فَدَعَا عَلَيْهِمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخَذَ اللَّهُ عَزَّ وَجَلَّ بِأَبْصَارِهِمْ فَقَدِمْنَا إِلَيْهِمْ فَأَخَذْنَاهُمْ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلْ جِئْتُمْ فِي عَهْدِ أَحَدٍ أَوْ هَلْ جَعَلَ لَكُمْ أَحَدٌ أَمَانًا فَقَالُوا لَا فَخَلَّى سَبِيلَهُمْ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏وَهُوَ الَّذِي كَفَّ أَيْدِيَهُمْ عَنْكُمْ وَأَيْدِيَكُمْ عَنْهُمْ بِبَطْنِ ‏ ‏مَكَّةَ ‏ ‏مِنْ بَعْدِ أَنْ أَظْفَرَكُمْ عَلَيْهِمْ وَكَانَ اللَّهُ بِمَا تَعْمَلُونَ بَصِيرًا ‏} ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏قَالَ ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏فِي هَذَا الْحَدِيثِ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏وَقَالَ ‏ ‏حُسَيْنُ بْنُ وَاقِدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ ‏ ‏وَهَذَا الصَّوَابُ عِنْدِي إِنْ شَاءَ اللَّهُ ‏","","",""],[16199,16199,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْجُرَيْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي نَعَامَةَ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ مُغَفَّلٍ ‏ ‏سَمِعَ ابْنًا لَهُ يَقُولُ اللَّهُمَّ إِنِّي أَسْأَلُكَ الْقَصْرَ الْأَبْيَضَ مِنْ الْجَنَّةِ إِذَا دَخَلْتُهَا عَنْ يَمِينِي قَالَ فَقَالَ لَهُ يَا بُنَيَّ سَلْ اللَّهَ الْجَنَّةَ وَتَعَوَّذْهُ مِنْ النَّارِ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏سَيَكُونُ بَعْدِي قَوْمٌ مِنْ هَذِهِ الْأُمَّةِ ‏ ‏يَعْتَدُونَ ‏ ‏فِي الدُّعَاءِ وَالطَّهُورِ ‏","","",""],[16200,16200,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏وَحُمَيْدٌ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ رَفِيقٌ يُحِبُّ الرِّفْقَ وَيُعْطِي عَلَى الرِّفْقِ مَا لَا يُعْطِي عَلَى الْعُنْفِ ‏","","",""]];
